export const bioMaterials: AuthoredMaterial[] = [
  { id: "neet-biology-the-living-world-m01", topicId: "neet-biology-the-living-world", title: "The Living World & Taxonomy", content: `Living organisms share **growth, reproduction, metabolism, cellular organisation, consciousness, and self-replication**; metabolism is the only defining property, while consciousness is the defining feature of humans. **Taxonomy** classifies and names organisms. The **taxonomic hierarchy** (broadest → narrowest) is Kingdom → Phylum/Division → Class → Order → Family → Genus → Species. **Binomial nomenclature** (Linnaeus) gives each species a two-word Latin name (Genus species), italicised, with the genus capitalised. **Taxonomic aids** include herbaria, botanical gardens, museums, zoological parks, keys, and the type specimen (holotype).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-biological-classification-m01", topicId: "neet-biology-biological-classification", title: "Five Kingdom Classification", content: `**Whittaker's five kingdoms** (1969): **Monera** (prokaryotes — bacteria), **Protista** (unicellular eukaryotes), **Fungi** (heterotrophic, chitin cell wall), **Plantae** (autotrophs), **Animalia** (heterotrophs, no cell wall). Criteria: cell structure, body organisation, mode of nutrition, reproduction, and phylogeny. **Bacteria** are grouped by shape (cocci, bacilli, spirilla) and by nutrition (autotrophic/heterotrophic). **Archaebacteria** live in extreme habitats. **Viruses, viroids, and lichens** are not placed in the five kingdoms — a virus is a nucleoprotein needing a host; lichens are a fungus–alga symbiosis.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-plant-kingdom-m01", topicId: "neet-biology-plant-kingdom", title: "Plant Kingdom", content: `**Algae → Bryophytes → Pteridophytes → Gymnosperms → Angiosperms** shows increasing complexity. **Bryophytes** (mosses, liverworts) are the 'amphibians of the plant kingdom' — need water for fertilisation, dominant **gametophyte**. **Pteridophytes** (ferns) are the first **vascular** plants, dominant **sporophyte**. **Gymnosperms** have naked seeds (no ovary/fruit). **Angiosperms** have flowers, fruits and seeds enclosed in an ovary. **Alternation of generations** cycles between a haploid gametophyte and diploid sporophyte. Angiosperms show **double fertilisation** forming a triploid endosperm.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-animal-kingdom-m01", topicId: "neet-biology-animal-kingdom", title: "Animal Kingdom", content: `Animals are classified by **levels of organisation** (cellular → tissue → organ → organ-system), **symmetry** (asymmetrical, radial, bilateral), **germ layers** (diploblastic/triploblastic), **coelom** (acoelomate, pseudocoelomate, coelomate), and **segmentation/notochord**. Key phyla: **Porifera** (sponges, canal system), **Cnidaria** (nematocysts), **Platyhelminthes** (flatworms), **Aschelminthes** (roundworms), **Annelida** (segmented), **Arthropoda** (largest phylum, jointed legs), **Mollusca**, **Echinodermata** (water vascular system), and **Chordata** (notochord, dorsal nerve cord, pharyngeal gill slits).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-morphology-flowering-plants-m01", topicId: "neet-biology-morphology-flowering-plants", title: "Morphology of Flowering Plants", content: `The **root system** anchors and absorbs (tap root in dicots, fibrous in monocots). The **shoot** bears nodes, internodes, leaves, and buds. **Leaf venation** is reticulate (dicots) or parallel (monocots). The **flower** is the reproductive shoot: calyx (sepals), corolla (petals), androecium (stamens), gynoecium (carpels). **Aestivation, placentation** (marginal, axile, parietal), and **floral formulae** describe flowers. **Fruits** develop from the ovary; **seeds** from ovules. Inflorescence types are **racemose** (indefinite) and **cymose** (definite).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-anatomy-flowering-plants-m01", topicId: "neet-biology-anatomy-flowering-plants", title: "Anatomy of Flowering Plants", content: `Plant tissues are **meristematic** (dividing: apical, intercalary, lateral) or **permanent** (parenchyma, collenchyma, sclerenchyma; xylem and phloem). **Xylem** (tracheids, vessels, fibres, parenchyma) conducts water and gives support; **phloem** (sieve tubes, companion cells) conducts food. **Tissue systems**: epidermal, ground, and vascular. Dicot vs monocot stems/roots differ in vascular bundle arrangement (ring vs scattered). **Secondary growth** from the vascular cambium produces annual rings; **cork cambium** forms bark.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-structural-organisation-animals-m01", topicId: "neet-biology-structural-organisation-animals", title: "Structural Organisation in Animals", content: `Animal tissues are four types: **epithelial** (covering/lining — squamous, cuboidal, columnar; glandular), **connective** (loose/dense, cartilage, bone, blood — with matrix), **muscular** (skeletal, smooth, cardiac), and **neural** (neurons + neuroglia). **Epithelial** cells rest on a basement membrane; specialised junctions are tight, adhering, and gap junctions. In model organisms such as the **cockroach, frog and earthworm**, organ systems (digestive, circulatory, excretory, reproductive) integrate tissues into a functioning body.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-transport-in-plants-m01", topicId: "neet-biology-transport-in-plants", title: "Transport in Plants", content: `Movement occurs by **diffusion**, **facilitated diffusion**, and **active transport**. **Water potential** (Ψ) drives water; it falls with solutes (**solute/osmotic potential**) and rises with pressure (**pressure potential**). Water enters roots by osmosis and moves up via the **apoplast/symplast** pathways. The **transpiration pull–cohesion–tension** theory explains the ascent of sap: transpiration from leaves creates tension transmitted through continuous, cohesive water columns in the xylem. **Stomata** regulate transpiration (open when guard cells are turgid). **Phloem** transports food by the **pressure-flow (mass-flow)** mechanism, source to sink.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-mineral-nutrition-m01", topicId: "neet-biology-mineral-nutrition", title: "Mineral Nutrition", content: `Plants need **macronutrients** (C, H, O, N, P, K, Ca, Mg, S) and **micronutrients** (Fe, Mn, Zn, Cu, B, Mo, Cl, Ni). Essential elements act as components of biomolecules, enzyme activators, or in osmotic/electrochemical balance. **Nitrogen** is fixed biologically by **Rhizobium** (symbiotic, in legume root nodules) and free-living microbes via the enzyme **nitrogenase**; the **nod** genes and leghaemoglobin (oxygen scavenger) support this. Deficiency symptoms appear first in old or young leaves depending on mobility. **Hydroponics** grows plants in nutrient solutions.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-respiration-in-plants-m01", topicId: "neet-biology-respiration-in-plants", title: "Respiration in Plants", content: `**Glycolysis** (cytoplasm) splits glucose into two pyruvate, net 2 ATP + 2 NADH. Under aerobic conditions pyruvate enters mitochondria for the **Krebs (TCA) cycle**, generating NADH/FADH₂, which feed the **electron transport chain** and **oxidative phosphorylation** (ATP synthase). Complete aerobic oxidation of one glucose yields about **36–38 ATP**. **Fermentation** (anaerobic) converts pyruvate to lactic acid or ethanol + CO₂, giving only 2 ATP. The **respiratory quotient (RQ)** = CO₂ released / O₂ consumed: 1 for carbohydrates, <1 for fats, >1 for organic acids.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-plant-growth-development-m01", topicId: "neet-biology-plant-growth-development", title: "Plant Growth & Development", content: `Growth is **indeterminate** in plants (meristems). The five **plant growth regulators**: **auxins** (apical dominance, rooting, cell elongation), **gibberellins** (stem elongation, bolting, seed germination), **cytokinins** (cell division, delay senescence), **ethylene** (fruit ripening, abscission — the gaseous hormone), and **abscisic acid** (stress/'stress hormone', stomatal closure, dormancy). **Photoperiodism** (response to day length; short-day/long-day plants; the leaf perceives via phytochrome) and **vernalisation** (cold promotes flowering) control development. **Differentiation, dedifferentiation, and redifferentiation** shape plant form.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-locomotion-movement-m01", topicId: "neet-biology-locomotion-movement", title: "Locomotion & Movement", content: `Muscle contraction follows the **sliding filament theory**: actin (thin) filaments slide over myosin (thick) filaments, shortening the sarcomere; the A-band stays constant while the I-band and H-zone shorten. It requires **Ca²⁺** (unmasking actin sites), **ATP**, and the troponin–tropomyosin switch. The **skeletal system** (206 bones in adults) has **axial** (skull, vertebrae, ribs, sternum) and **appendicular** parts. **Joints** are fibrous, cartilaginous, or synovial (freely movable). Disorders include myasthenia gravis, arthritis, osteoporosis, and gout.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-chemical-coordination-hormones-m01", topicId: "neet-biology-chemical-coordination-hormones", title: "Chemical Coordination & Hormones", content: `The **endocrine system** uses ductless glands secreting hormones into blood. The **hypothalamus** controls the **pituitary** (master gland). Key hormones: **thyroxine** (T₄, needs iodine; deficiency → goitre), **insulin/glucagon** (pancreatic islets, glucose balance; insulin lowers blood sugar), **adrenaline** (adrenal medulla, 'fight or flight'), **cortisol** (adrenal cortex), **parathormone** (raises blood Ca²⁺). Hormones act via **membrane receptors** (peptide/amine hormones → second messengers like cAMP) or **intracellular receptors** (steroid/thyroid hormones → gene expression). Feedback loops keep levels regulated.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-m01", topicId: "neet-biology-sexual-reproduction-flowering-plants", title: "Sexual Reproduction in Flowering Plants", content: `The **anther** produces pollen (microspores) by microsporogenesis; the **ovule** produces the female gametophyte (embryo sac, typically 7-celled/8-nucleate) by megasporogenesis. After **pollination** (self or cross), the pollen tube delivers two male gametes for **double fertilisation**: one fuses with the egg (→ diploid zygote), the other with the two polar nuclei (→ triploid **endosperm**) — described by Nawaschin. The zygote becomes the embryo; the ovule becomes the seed; the ovary becomes the fruit. **Apomixis** is seed formation without fertilisation; **polyembryony** is many embryos per seed.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-reproductive-health-m01", topicId: "neet-biology-reproductive-health", title: "Reproductive Health", content: `Reproductive health means healthy reproductive functioning and behaviour. **Contraception** methods: barrier (condoms), IUDs (Copper-T), hormonal pills, surgical (vasectomy/tubectomy), and natural (rhythm, withdrawal). **MTP** (medical termination of pregnancy) is legal to a limit in India. **STIs** include gonorrhoea, syphilis, and HIV/AIDS. **Infertility** is addressed by **ART**: IVF (test-tube baby, ZIFT/GIFT), ICSI, and artificial insemination. **Amniocentesis** (misused for sex determination — legally banned) checks foetal disorders. Programmes like RCH promote awareness and small families.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-microbes-human-welfare-m01", topicId: "neet-biology-microbes-human-welfare", title: "Microbes in Human Welfare", content: `Microbes are used in **food** (LAB/Lactobacillus curdles milk and adds vitamin B₁₂; yeast in bread/alcohol; 'Swiss cheese' holes from Propionibacterium CO₂), **beverages** (Saccharomyces cerevisiae ferments sugars to ethanol), and **industry**. **Antibiotics**: Penicillin from Penicillium notatum (Fleming). **Fermenters (bioreactors)** scale production of enzymes (lipase, pectinase), organic acids (citric acid — Aspergillus), and drugs (statins from Monascus; cyclosporin A — immunosuppressant — from Trichoderma). In **sewage treatment**, aerobic microbes form flocs; **biogas** (mainly methane) is produced by **methanogens** (e.g., Methanobacterium). **Biofertilisers** and **biocontrol** (Bacillus thuringiensis, Baculovirus, mycorrhiza) reduce chemical use.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-biotechnology-applications-m01", topicId: "neet-biology-biotechnology-applications", title: "Biotechnology & its Applications", content: `**Applications** span agriculture, medicine, and industry. **Bt crops** (Bt cotton/corn) carry *cry* genes from **Bacillus thuringiensis** producing insecticidal proteins. **RNAi** protects plants (e.g., against nematodes in tobacco). Medicines made by rDNA: **human insulin (Humulin)** — two chains A and B produced in E. coli then joined; **gene therapy** (e.g., ADA deficiency) inserts functional genes. **Molecular diagnostics** use PCR and ELISA to detect pathogens early. **Transgenic animals** produce useful proteins (e.g., α-1-antitrypsin). Ethical oversight (GEAC) and **biopiracy/patent** concerns accompany the technology.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-organisms-populations-m01", topicId: "neet-biology-organisms-populations", title: "Organisms & Populations", content: `Organisms cope with their environment by **regulation, conformation, migration, or suspension** (dormancy). **Population attributes**: density, birth/death rates, sex ratio, and age pyramids. Growth models: **exponential** dN/dt = rN (J-shaped, unlimited resources) and **logistic** dN/dt = rN(K−N)/K (S-shaped, with carrying capacity K). **Population interactions**: mutualism (+/+), competition (−/−), predation (+/−), parasitism (+/−), commensalism (+/0), and amensalism (−/0). Adaptations (e.g., Allen's/Bergmann's rules, kangaroo rat's water economy) fit organisms to their niche.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-biology-environmental-issues-m01", topicId: "neet-biology-environmental-issues", title: "Environmental Issues", content: `**Air pollution** is controlled by electrostatic precipitators and scrubbers; vehicular pollution by catalytic converters and CNG (Delhi case). **Water pollution**: BOD rises with organic waste; **eutrophication** is nutrient over-enrichment causing algal blooms and oxygen depletion. **Sewage** is treated to lower BOD. **Global warming** results from greenhouse gases (CO₂, CH₄, N₂O, CFCs). **Ozone depletion** (CFCs → Cl radicals; measured in Dobson units; the Montreal Protocol regulates CFCs) increases UV. Other issues: solid/e-waste, deforestation, and the need for reforestation and integrated waste management.`, estimatedReadTime: 2, orderIndex: 0 }
];

