  { id: "neet-biology-plant-animal-tissues-q10", topicId: "neet-biology-plant-animal-tissues", text: "Cardiac muscle is characterised as:", optionA: "Voluntary and striated", optionB: "Involuntary and striated", optionC: "Voluntary and smooth", optionD: "Involuntary and smooth", correctOption: "B", explanation: "Cardiac muscle is striated but involuntary, contracting rhythmically without fatigue.", orderIndex: 9 },
  { id: "neet-biology-plant-animal-tissues-q11", topicId: "neet-biology-plant-animal-tissues", text: "Blood is classified as which type of animal tissue?", optionA: "Epithelial", optionB: "Connective", optionC: "Muscular", optionD: "Neural", correctOption: "B", explanation: "Blood is a fluid connective tissue with a liquid matrix (plasma).", orderIndex: 10 },
  { id: "neet-biology-plant-animal-tissues-q12", topicId: "neet-biology-plant-animal-tissues", text: "Which meristem is responsible for increase in girth (secondary growth)?", optionA: "Apical meristem", optionB: "Lateral meristem", optionC: "Intercalary meristem", optionD: "Ground meristem", correctOption: "B", explanation: "Lateral meristems (vascular and cork cambium) add to the plant's thickness.", orderIndex: 11 },
  // Breathing & Exchange of Gases
  { id: "neet-biology-breathing-exchange-of-gases-q09", topicId: "neet-biology-breathing-exchange-of-gases", text: "Most oxygen is transported in blood as:", optionA: "Dissolved in plasma", optionB: "Oxyhaemoglobin", optionC: "Bicarbonate", optionD: "Carbaminohaemoglobin", correctOption: "B", explanation: "About 97% of O₂ is carried bound to haemoglobin as oxyhaemoglobin.", orderIndex: 8 },
  { id: "neet-biology-breathing-exchange-of-gases-q10", topicId: "neet-biology-breathing-exchange-of-gases", text: "The exchange of gases in the lungs occurs at the:", optionA: "Bronchi", optionB: "Alveoli", optionC: "Trachea", optionD: "Larynx", correctOption: "B", explanation: "Alveoli provide a thin, large surface for gas exchange by diffusion.", orderIndex: 9 },
  { id: "neet-biology-breathing-exchange-of-gases-q11", topicId: "neet-biology-breathing-exchange-of-gases", text: "Most carbon dioxide is transported in blood as:", optionA: "Bicarbonate ions", optionB: "Dissolved gas only", optionC: "Carbonic acid crystals", optionD: "Bound to plasma proteins only", correctOption: "A", explanation: "About 70% of CO₂ is carried as bicarbonate (HCO₃⁻) formed in red blood cells.", orderIndex: 10 },
  { id: "neet-biology-breathing-exchange-of-gases-q12", topicId: "neet-biology-breathing-exchange-of-gases", text: "The volume of air breathed in or out during normal quiet breathing is the:", optionA: "Tidal volume", optionB: "Vital capacity", optionC: "Residual volume", optionD: "Total lung capacity", correctOption: "A", explanation: "Tidal volume (~500 mL) is the air exchanged in a normal breath.", orderIndex: 11 },
  // Body Fluids & Circulation
  { id: "neet-biology-body-fluids-circulation-q09", topicId: "neet-biology-body-fluids-circulation", text: "The natural pacemaker of the human heart is the:", optionA: "AV node", optionB: "SA node", optionC: "Purkinje fibres", optionD: "Bundle of His", correctOption: "B", explanation: "The sino-atrial (SA) node initiates each heartbeat and sets the rhythm.", orderIndex: 8 },
  { id: "neet-biology-body-fluids-circulation-q10", topicId: "neet-biology-body-fluids-circulation", text: "Which blood cells are involved in clotting?", optionA: "Erythrocytes", optionB: "Platelets (thrombocytes)", optionC: "Lymphocytes", optionD: "Monocytes", correctOption: "B", explanation: "Platelets release clotting factors and help form the blood clot.", orderIndex: 9 },
  { id: "neet-biology-body-fluids-circulation-q11", topicId: "neet-biology-body-fluids-circulation", text: "The universal blood donor group is:", optionA: "AB positive", optionB: "O negative", optionC: "A positive", optionD: "B negative", correctOption: "B", explanation: "O negative has no A, B, or Rh antigens, so it can be given to any recipient.", orderIndex: 10 },
  { id: "neet-biology-body-fluids-circulation-q12", topicId: "neet-biology-body-fluids-circulation", text: "In double circulation, blood passes through the heart:", optionA: "Once per cycle", optionB: "Twice per cycle", optionC: "Thrice per cycle", optionD: "Never", correctOption: "B", explanation: "Double circulation sends blood through the heart twice — pulmonary and systemic circuits.", orderIndex: 11 },
  // Excretory Products
  { id: "neet-biology-excretory-products-elimination-q09", topicId: "neet-biology-excretory-products-elimination", text: "The functional unit of the kidney is the:", optionA: "Neuron", optionB: "Nephron", optionC: "Alveolus", optionD: "Villus", correctOption: "B", explanation: "The nephron filters blood and forms urine; each kidney has about a million.", orderIndex: 8 },
  { id: "neet-biology-excretory-products-elimination-q10", topicId: "neet-biology-excretory-products-elimination", text: "Humans are ureotelic, meaning they mainly excrete:", optionA: "Ammonia", optionB: "Urea", optionC: "Uric acid", optionD: "Amino acids", correctOption: "B", explanation: "Humans convert toxic ammonia to less toxic urea for excretion (ureotelic).", orderIndex: 9 },
  { id: "neet-biology-excretory-products-elimination-q11", topicId: "neet-biology-excretory-products-elimination", text: "Filtration of blood occurs in the:", optionA: "Loop of Henle", optionB: "Malpighian corpuscle (glomerulus + Bowman's capsule)", optionC: "Collecting duct", optionD: "Ureter", correctOption: "B", explanation: "Ultrafiltration occurs at the glomerulus into Bowman's capsule.", orderIndex: 10 },
  { id: "neet-biology-excretory-products-elimination-q12", topicId: "neet-biology-excretory-products-elimination", text: "ADH (vasopressin) regulates urine by promoting:", optionA: "Water reabsorption in the kidney", optionB: "Water loss", optionC: "Salt excretion", optionD: "Glucose excretion", correctOption: "A", explanation: "ADH increases water reabsorption from the collecting ducts, concentrating urine.", orderIndex: 11 },
  // Neural Control
  { id: "neet-biology-neural-control-coordination-q09", topicId: "neet-biology-neural-control-coordination", text: "The structural and functional unit of the nervous system is the:", optionA: "Nephron", optionB: "Neuron", optionC: "Neuroglia", optionD: "Axon hillock", correctOption: "B", explanation: "The neuron is the basic unit transmitting nerve impulses.", orderIndex: 8 },
  { id: "neet-biology-neural-control-coordination-q10", topicId: "neet-biology-neural-control-coordination", text: "The resting membrane potential of a neuron is maintained mainly by the:", optionA: "Sodium–potassium pump", optionB: "Calcium pump", optionC: "Proton pump", optionD: "Chloride channel", correctOption: "A", explanation: "The Na⁺/K⁺ ATPase pumps 3 Na⁺ out and 2 K⁺ in, maintaining the resting potential.", orderIndex: 9 },
  { id: "neet-biology-neural-control-coordination-q11", topicId: "neet-biology-neural-control-coordination", text: "Across a synapse, the nerve impulse is transmitted by:", optionA: "Direct electrical contact only", optionB: "Neurotransmitters", optionC: "Hormones in blood", optionD: "The myelin sheath", correctOption: "B", explanation: "Chemical synapses release neurotransmitters (e.g., acetylcholine) into the synaptic cleft.", orderIndex: 10 },
  { id: "neet-biology-neural-control-coordination-q12", topicId: "neet-biology-neural-control-coordination", text: "The part of the brain controlling balance and coordination is the:", optionA: "Cerebrum", optionB: "Cerebellum", optionC: "Medulla oblongata", optionD: "Hypothalamus", correctOption: "B", explanation: "The cerebellum coordinates muscular activity and maintains balance and posture.", orderIndex: 11 },
  // Principles of Inheritance
  { id: "neet-biology-principles-inheritance-variation-q09", topicId: "neet-biology-principles-inheritance-variation", text: "Mendel's law of segregation states that:", optionA: "Alleles blend in offspring", optionB: "Paired alleles separate during gamete formation", optionC: "All genes are linked", optionD: "Traits skip generations always", correctOption: "B", explanation: "Each gamete receives only one of the two alleles for a trait (segregation).", orderIndex: 8 },
  { id: "neet-biology-principles-inheritance-variation-q10", topicId: "neet-biology-principles-inheritance-variation", text: "The phenotypic ratio of a monohybrid cross (F2) is:", optionA: "9:3:3:1", optionB: "3:1", optionC: "1:1", optionD: "1:2:1", correctOption: "B", explanation: "A monohybrid F2 shows a 3:1 dominant-to-recessive phenotypic ratio.", orderIndex: 9 },
  { id: "neet-biology-principles-inheritance-variation-q11", topicId: "neet-biology-principles-inheritance-variation", text: "Colour blindness and haemophilia are examples of:", optionA: "Autosomal dominant traits", optionB: "X-linked recessive traits", optionC: "Y-linked traits", optionD: "Mitochondrial traits", correctOption: "B", explanation: "These are X-linked recessive disorders, more common in males.", orderIndex: 10 },
  { id: "neet-biology-principles-inheritance-variation-q12", topicId: "neet-biology-principles-inheritance-variation", text: "A dihybrid cross F2 gives a phenotypic ratio of:", optionA: "3:1", optionB: "9:3:3:1", optionC: "1:1", optionD: "1:2:1", correctOption: "B", explanation: "Independent assortment of two traits gives the classic 9:3:3:1 ratio.", orderIndex: 11 },
  // Molecular Basis of Inheritance
  { id: "neet-biology-molecular-basis-inheritance-q09", topicId: "neet-biology-molecular-basis-inheritance", text: "In DNA, adenine pairs with:", optionA: "Guanine", optionB: "Thymine", optionC: "Cytosine", optionD: "Uracil", correctOption: "B", explanation: "In DNA, A pairs with T (two hydrogen bonds) and G with C (three).", orderIndex: 8 },
  { id: "neet-biology-molecular-basis-inheritance-q10", topicId: "neet-biology-molecular-basis-inheritance", text: "The process of making mRNA from a DNA template is called:", optionA: "Replication", optionB: "Transcription", optionC: "Translation", optionD: "Transduction", correctOption: "B", explanation: "Transcription synthesises RNA from a DNA template using RNA polymerase.", orderIndex: 9 },
  { id: "neet-biology-molecular-basis-inheritance-q11", topicId: "neet-biology-molecular-basis-inheritance", text: "The experiment establishing DNA as the genetic material in bacteriophages was by:", optionA: "Hershey and Chase", optionB: "Mendel", optionC: "Darwin", optionD: "Morgan", correctOption: "A", explanation: "Hershey and Chase used radioactive labelling to show DNA (not protein) is the genetic material.", orderIndex: 10 },
  { id: "neet-biology-molecular-basis-inheritance-q12", topicId: "neet-biology-molecular-basis-inheritance", text: "DNA replication is described as semi-conservative, meaning each new molecule has:", optionA: "Two new strands", optionB: "One parental and one new strand", optionC: "Two parental strands", optionD: "Only RNA", correctOption: "B", explanation: "Meselson and Stahl showed each daughter DNA keeps one original strand and one new one.", orderIndex: 11 },
  // Evolution
  { id: "neet-biology-evolution-q09", topicId: "neet-biology-evolution", text: "Natural selection as the mechanism of evolution was proposed by:", optionA: "Lamarck", optionB: "Charles Darwin", optionC: "Mendel", optionD: "Hugo de Vries", correctOption: "B", explanation: "Darwin proposed natural selection ('survival of the fittest') in On the Origin of Species.", orderIndex: 8 },
  { id: "neet-biology-evolution-q10", topicId: "neet-biology-evolution", text: "Homologous organs (e.g., forelimbs of humans and whales) indicate:", optionA: "Convergent evolution", optionB: "Divergent evolution (common ancestry)", optionC: "No relationship", optionD: "Spontaneous generation", correctOption: "B", explanation: "Homologous organs share structure from a common ancestor — divergent evolution.", orderIndex: 9 },
  { id: "neet-biology-evolution-q11", topicId: "neet-biology-evolution", text: "The Hardy–Weinberg principle describes conditions under which:", optionA: "Allele frequencies remain constant across generations", optionB: "Mutations always occur", optionC: "Natural selection is strong", optionD: "Populations always evolve", correctOption: "A", explanation: "In an idealised population (no selection, mutation, migration, drift), allele frequencies stay constant.", orderIndex: 10 },
  { id: "neet-biology-evolution-q12", topicId: "neet-biology-evolution", text: "Analogous organs (e.g., wings of insects and birds) are the result of:", optionA: "Convergent evolution", optionB: "Divergent evolution", optionC: "Common ancestry", optionD: "Genetic drift", correctOption: "A", explanation: "Analogous organs have different origins but similar function — convergent evolution.", orderIndex: 11 },
  // Human Reproduction
  { id: "neet-biology-human-reproduction-q09", topicId: "neet-biology-human-reproduction", text: "The site of fertilisation in humans is the:", optionA: "Uterus", optionB: "Ampulla of the fallopian tube", optionC: "Ovary", optionD: "Cervix", correctOption: "B", explanation: "Fertilisation normally occurs in the ampullary region of the oviduct.", orderIndex: 8 },
  { id: "neet-biology-human-reproduction-q10", topicId: "neet-biology-human-reproduction", text: "The process of sperm formation in the testes is called:", optionA: "Oogenesis", optionB: "Spermatogenesis", optionC: "Ovulation", optionD: "Implantation", correctOption: "B", explanation: "Spermatogenesis produces sperm in the seminiferous tubules of the testes.", orderIndex: 9 },
  { id: "neet-biology-human-reproduction-q11", topicId: "neet-biology-human-reproduction", text: "The hormone that maintains pregnancy by sustaining the corpus luteum early on is:", optionA: "hCG", optionB: "FSH", optionC: "LH", optionD: "Oxytocin", correctOption: "A", explanation: "Human chorionic gonadotropin (hCG) from the embryo maintains the corpus luteum.", orderIndex: 10 },
  { id: "neet-biology-human-reproduction-q12", topicId: "neet-biology-human-reproduction", text: "Implantation of the blastocyst occurs in the:", optionA: "Ovary", optionB: "Endometrium of the uterus", optionC: "Fallopian tube", optionD: "Vagina", correctOption: "B", explanation: "The blastocyst embeds in the uterine endometrium during implantation.", orderIndex: 11 },
  // Biotechnology Principles
  { id: "neet-biology-biotechnology-principles-q09", topicId: "neet-biology-biotechnology-principles", text: "Restriction enzymes are used in genetic engineering to:", optionA: "Join DNA fragments", optionB: "Cut DNA at specific sequences", optionC: "Replicate DNA", optionD: "Translate mRNA", correctOption: "B", explanation: "Restriction endonucleases cut DNA at specific palindromic recognition sites ('molecular scissors').", orderIndex: 8 },
  { id: "neet-biology-biotechnology-principles-q10", topicId: "neet-biology-biotechnology-principles", text: "The enzyme that joins DNA fragments is:", optionA: "DNA ligase", optionB: "DNA polymerase", optionC: "Restriction enzyme", optionD: "Helicase", correctOption: "A", explanation: "DNA ligase seals the phosphodiester backbone, joining fragments ('molecular glue').", orderIndex: 9 },
  { id: "neet-biology-biotechnology-principles-q11", topicId: "neet-biology-biotechnology-principles", text: "PCR (polymerase chain reaction) is used to:", optionA: "Cut DNA", optionB: "Amplify DNA in vitro", optionC: "Translate proteins", optionD: "Sequence proteins", correctOption: "B", explanation: "PCR amplifies specific DNA segments using primers and a thermostable Taq polymerase.", orderIndex: 10 },
  { id: "neet-biology-biotechnology-principles-q12", topicId: "neet-biology-biotechnology-principles", text: "A commonly used vector to carry foreign DNA into bacteria is a:", optionA: "Ribosome", optionB: "Plasmid", optionC: "Lysosome", optionD: "Centriole", correctOption: "B", explanation: "Plasmids are small, self-replicating circular DNA used as cloning vectors.", orderIndex: 11 },
  // Ecosystem & Biodiversity
  { id: "neet-biology-ecosystem-biodiversity-q09", topicId: "neet-biology-ecosystem-biodiversity", text: "The flow of energy through an ecosystem is:", optionA: "Cyclic", optionB: "Unidirectional", optionC: "Bidirectional", optionD: "Absent", correctOption: "B", explanation: "Energy flows one way (sun → producers → consumers), dissipating as heat, unlike cycling nutrients.", orderIndex: 8 },
  { id: "neet-biology-ecosystem-biodiversity-q10", topicId: "neet-biology-ecosystem-biodiversity", text: "Organisms that make their own food are called:", optionA: "Producers (autotrophs)", optionB: "Consumers", optionC: "Decomposers", optionD: "Parasites", correctOption: "A", explanation: "Autotrophs (e.g., green plants) synthesise organic food and form the base of food chains.", orderIndex: 9 },
  { id: "neet-biology-ecosystem-biodiversity-q11", topicId: "neet-biology-ecosystem-biodiversity", text: "According to the 10% law, energy transferred to the next trophic level is about:", optionA: "10%", optionB: "50%", optionC: "90%", optionD: "100%", correctOption: "A", explanation: "Only about 10% of energy passes to the next trophic level; the rest is lost as heat.", orderIndex: 10 },
  { id: "neet-biology-ecosystem-biodiversity-q12", topicId: "neet-biology-ecosystem-biodiversity", text: "The greatest biodiversity on Earth is found in:", optionA: "Deserts", optionB: "Tropical rainforests", optionC: "Tundra", optionD: "Grasslands", correctOption: "B", explanation: "Tropical rainforests, especially the Amazon, harbour the highest species diversity.", orderIndex: 11 },
  // Human Health & Disease
  { id: "neet-biology-human-health-disease-q09", topicId: "neet-biology-human-health-disease", text: "Malaria is caused by which pathogen?", optionA: "A bacterium", optionB: "Plasmodium (a protozoan)", optionC: "A virus", optionD: "A fungus", correctOption: "B", explanation: "Malaria is caused by Plasmodium, transmitted by the female Anopheles mosquito.", orderIndex: 8 },
  { id: "neet-biology-human-health-disease-q10", topicId: "neet-biology-human-health-disease", text: "Antibodies are produced by which type of cell?", optionA: "T lymphocytes", optionB: "B lymphocytes", optionC: "Red blood cells", optionD: "Platelets", correctOption: "B", explanation: "B lymphocytes differentiate into plasma cells that secrete antibodies (humoral immunity).", orderIndex: 9 },
  { id: "neet-biology-human-health-disease-q11", topicId: "neet-biology-human-health-disease", text: "AIDS is caused by:", optionA: "HIV, which attacks helper T-cells", optionB: "A bacterium", optionC: "A protozoan", optionD: "A fungus", correctOption: "A", explanation: "HIV infects and destroys helper T-lymphocytes, weakening the immune system.", orderIndex: 10 },
  { id: "neet-biology-human-health-disease-q12", topicId: "neet-biology-human-health-disease", text: "Active immunity is acquired by:", optionA: "Receiving ready-made antibodies", optionB: "Exposure to an antigen (infection or vaccine)", optionC: "Mother's milk only", optionD: "Blood transfusion", correctOption: "B", explanation: "Active immunity develops when the body makes its own antibodies after antigen exposure.", orderIndex: 11 },

  // ── New topic: The Living World & Taxonomy ──
  { id: "neet-biology-the-living-world-q01", topicId: "neet-biology-the-living-world", text: "The system of giving two-word Latin names to species is called:", optionA: "Vernacular naming", optionB: "Binomial nomenclature", optionC: "Trinomial nomenclature", optionD: "Common naming", correctOption: "B", explanation: "Binomial nomenclature (Linnaeus) gives each species a Genus + species name.", orderIndex: 0 },
  { id: "neet-biology-the-living-world-q02", topicId: "neet-biology-the-living-world", text: "The correct sequence of taxonomic categories from broad to narrow is:", optionA: "Species → Genus → Family → Kingdom", optionB: "Kingdom → Phylum → Class → Order → Family → Genus → Species", optionC: "Genus → Species → Family → Order", optionD: "Order → Class → Kingdom → Species", correctOption: "B", explanation: "The hierarchy runs Kingdom → Phylum → Class → Order → Family → Genus → Species.", orderIndex: 1 },
  { id: "neet-biology-the-living-world-q03", topicId: "neet-biology-the-living-world", text: "The only defining characteristic common to all living organisms is:", optionA: "Consciousness", optionB: "Metabolism", optionC: "Locomotion", optionD: "Photosynthesis", correctOption: "B", explanation: "Metabolism (the sum of chemical reactions) is a defining property of all living things.", orderIndex: 2 },
  { id: "neet-biology-the-living-world-q04", topicId: "neet-biology-the-living-world", text: "In a scientific name, the genus name is:", optionA: "Written in lowercase", optionB: "Capitalised", optionC: "Never italicised", optionD: "Placed second", correctOption: "B", explanation: "The genus is capitalised and the species name is lowercase; both are italicised.", orderIndex: 3 },
  { id: "neet-biology-the-living-world-q05", topicId: "neet-biology-the-living-world", text: "A group of organisms that can interbreed to produce fertile offspring is a:", optionA: "Genus", optionB: "Species", optionC: "Family", optionD: "Order", correctOption: "B", explanation: "A species is the basic unit — a group of interbreeding, reproductively isolated organisms.", orderIndex: 4 },
  { id: "neet-biology-the-living-world-q06", topicId: "neet-biology-the-living-world", text: "Which is a taxonomic aid that stores dried, pressed plant specimens?", optionA: "Zoo", optionB: "Herbarium", optionC: "Aquarium", optionD: "Botanical key", correctOption: "B", explanation: "A herbarium is a store of dried, pressed, and preserved plant specimens on sheets.", orderIndex: 5 },
  { id: "neet-biology-the-living-world-q07", topicId: "neet-biology-the-living-world", text: "Taxonomy that deals with naming organisms is:", optionA: "Nomenclature", optionB: "Identification only", optionC: "Ecology", optionD: "Physiology", correctOption: "A", explanation: "Nomenclature is the process of assigning standardised scientific names.", orderIndex: 6 },
  { id: "neet-biology-the-living-world-q08", topicId: "neet-biology-the-living-world", text: "The defining property unique to human beings among living organisms is:", optionA: "Growth", optionB: "Consciousness (self-awareness)", optionC: "Reproduction", optionD: "Respiration", correctOption: "B", explanation: "Self-consciousness is regarded as the defining feature distinguishing humans.", orderIndex: 7 },
  { id: "neet-biology-the-living-world-q09", topicId: "neet-biology-the-living-world", text: "ICBN stands for the international code that governs naming of:", optionA: "Animals", optionB: "Plants (botanical names)", optionC: "Bacteria only", optionD: "Viruses", correctOption: "B", explanation: "The International Code of Botanical (now algae, fungi and plants) Nomenclature governs plant names.", orderIndex: 8 },
  { id: "neet-biology-the-living-world-q10", topicId: "neet-biology-the-living-world", text: "A monograph contains information on:", optionA: "All members of a group at one time", optionB: "A single taxon in detail", optionC: "Only fossils", optionD: "Only local flora", correctOption: "B", explanation: "A monograph gives comprehensive information on any one taxon.", orderIndex: 9 },
  { id: "neet-biology-the-living-world-q11", topicId: "neet-biology-the-living-world", text: "Growth in living organisms is defined as an increase in:", optionA: "Only external size", optionB: "Mass and number of cells", optionC: "Temperature", optionD: "Colour", correctOption: "B", explanation: "Biological growth is an increase in cell number and body mass (intrinsic in living things).", orderIndex: 10 },
  { id: "neet-biology-the-living-world-q12", topicId: "neet-biology-the-living-world", text: "The taxonomic category between Class and Family is:", optionA: "Order", optionB: "Genus", optionC: "Phylum", optionD: "Species", correctOption: "A", explanation: "Order lies between Class and Family in the taxonomic hierarchy.", orderIndex: 11 },

  // ── New topic: Biological Classification ──
  { id: "neet-biology-biological-classification-q01", topicId: "neet-biology-biological-classification", text: "The five-kingdom classification was proposed by:", optionA: "Linnaeus", optionB: "R. H. Whittaker", optionC: "Ernst Haeckel", optionD: "Carl Woese", correctOption: "B", explanation: "Whittaker (1969) proposed the five kingdoms: Monera, Protista, Fungi, Plantae, Animalia.", orderIndex: 0 },
  { id: "neet-biology-biological-classification-q02", topicId: "neet-biology-biological-classification", text: "Kingdom Monera consists of:", optionA: "Eukaryotic algae", optionB: "Prokaryotes (bacteria)", optionC: "Fungi", optionD: "Protozoa", correctOption: "B", explanation: "Monera includes all prokaryotic organisms — the bacteria.", orderIndex: 1 },
  { id: "neet-biology-biological-classification-q03", topicId: "neet-biology-biological-classification", text: "Which kingdom includes heterotrophic organisms with a chitinous cell wall?", optionA: "Plantae", optionB: "Fungi", optionC: "Monera", optionD: "Animalia", correctOption: "B", explanation: "Fungi are heterotrophs with cell walls made of chitin.", orderIndex: 2 },
  { id: "neet-biology-biological-classification-q04", topicId: "neet-biology-biological-classification", text: "Archaebacteria that live in extreme salty habitats are called:", optionA: "Halophiles", optionB: "Methanogens", optionC: "Thermoacidophiles", optionD: "Cyanobacteria", correctOption: "A", explanation: "Halophiles are archaebacteria adapted to extreme salt concentrations.", orderIndex: 3 },
  { id: "neet-biology-biological-classification-q05", topicId: "neet-biology-biological-classification", text: "Lichens are a symbiotic association between:", optionA: "A fungus and an alga", optionB: "Two fungi", optionC: "A plant and a bacterium", optionD: "Two algae", correctOption: "A", explanation: "A lichen is a mutualism between a fungus (mycobiont) and an alga/cyanobacterium (phycobiont).", orderIndex: 4 },
  { id: "neet-biology-biological-classification-q06", topicId: "neet-biology-biological-classification", text: "Viruses are not included in the five-kingdom system because they:", optionA: "Are too large", optionB: "Are non-cellular and need a host to reproduce", optionC: "Have chlorophyll", optionD: "Are prokaryotes", correctOption: "B", explanation: "Viruses are acellular obligate parasites, so they fall outside the cellular kingdoms.", orderIndex: 5 },
  { id: "neet-biology-biological-classification-q07", topicId: "neet-biology-biological-classification", text: "Dinoflagellates and diatoms belong to which kingdom?", optionA: "Monera", optionB: "Protista", optionC: "Fungi", optionD: "Plantae", correctOption: "B", explanation: "These unicellular eukaryotic algae are placed in kingdom Protista.", orderIndex: 6 },
  { id: "neet-biology-biological-classification-q08", topicId: "neet-biology-biological-classification", text: "The infective, protein-only agents causing diseases like mad-cow disease are:", optionA: "Viroids", optionB: "Prions", optionC: "Bacteria", optionD: "Plasmids", correctOption: "B", explanation: "Prions are abnormally folded infectious proteins responsible for spongiform encephalopathies.", orderIndex: 7 },
  { id: "neet-biology-biological-classification-q09", topicId: "neet-biology-biological-classification", text: "Which is an example of a symbiotic, nitrogen-fixing cyanobacterium/bacterium?", optionA: "Rhizobium", optionB: "Escherichia coli", optionC: "Lactobacillus", optionD: "Clostridium botulinum", correctOption: "A", explanation: "Rhizobium fixes nitrogen symbiotically in the root nodules of legumes.", orderIndex: 8 },
  { id: "neet-biology-biological-classification-q10", topicId: "neet-biology-biological-classification", text: "Slime moulds are classified under:", optionA: "Fungi", optionB: "Protista", optionC: "Monera", optionD: "Animalia", correctOption: "B", explanation: "Slime moulds are saprophytic protists that form plasmodia.", orderIndex: 9 },
  { id: "neet-biology-biological-classification-q11", topicId: "neet-biology-biological-classification", text: "Viroids differ from viruses in that they consist of:", optionA: "Only free RNA without a protein coat", optionB: "Only protein", optionC: "DNA and protein", optionD: "A cell wall", correctOption: "A", explanation: "Viroids are small, naked, single-stranded RNA molecules lacking a protein coat.", orderIndex: 10 },
  { id: "neet-biology-biological-classification-q12", topicId: "neet-biology-biological-classification", text: "The mode of nutrition in most fungi is:", optionA: "Autotrophic", optionB: "Heterotrophic (saprophytic/parasitic)", optionC: "Chemosynthetic", optionD: "Photosynthetic", correctOption: "B", explanation: "Fungi are heterotrophs, absorbing nutrients as saprophytes, parasites, or symbionts.", orderIndex: 11 },

  // ── New topic: Plant Kingdom ──
  { id: "neet-biology-plant-kingdom-q01", topicId: "neet-biology-plant-kingdom", text: "Bryophytes are often called the 'amphibians of the plant kingdom' because they:", optionA: "Live only in water", optionB: "Need water for fertilisation but live on land", optionC: "Are aquatic animals", optionD: "Have no cells", correctOption: "B", explanation: "Bryophytes live on land but require water for the sperm to reach the egg.", orderIndex: 0 },
  { id: "neet-biology-plant-kingdom-q02", topicId: "neet-biology-plant-kingdom", text: "The first vascular plants (with xylem and phloem) are the:", optionA: "Algae", optionB: "Bryophytes", optionC: "Pteridophytes", optionD: "Fungi", correctOption: "C", explanation: "Pteridophytes (e.g., ferns) are the earliest plants with true vascular tissue.", orderIndex: 1 },
  { id: "neet-biology-plant-kingdom-q03", topicId: "neet-biology-plant-kingdom", text: "Gymnosperms are distinguished by having:", optionA: "Flowers and fruits", optionB: "Naked seeds (not enclosed in an ovary)", optionC: "No seeds", optionD: "Spores only", correctOption: "B", explanation: "Gymnosperms bear naked seeds because there is no ovary enclosing the ovules.", orderIndex: 2 },
  { id: "neet-biology-plant-kingdom-q04", topicId: "neet-biology-plant-kingdom", text: "In bryophytes, the dominant, photosynthetic phase of the life cycle is the:", optionA: "Sporophyte", optionB: "Gametophyte", optionC: "Zygote", optionD: "Seed", correctOption: "B", explanation: "In bryophytes the haploid gametophyte is dominant and the sporophyte is dependent on it.", orderIndex: 3 },
  { id: "neet-biology-plant-kingdom-q05", topicId: "neet-biology-plant-kingdom", text: "Double fertilisation and triploid endosperm are characteristic of:", optionA: "Angiosperms", optionB: "Gymnosperms", optionC: "Pteridophytes", optionD: "Bryophytes", correctOption: "A", explanation: "Only angiosperms show double fertilisation forming a triploid endosperm.", orderIndex: 4 },
  { id: "neet-biology-plant-kingdom-q06", topicId: "neet-biology-plant-kingdom", text: "The life cycle showing an alternation between haploid and diploid phases is called:", optionA: "Alternation of generations", optionB: "Metagenesis of animals", optionC: "Parthenogenesis", optionD: "Binary fission", correctOption: "A", explanation: "Plants alternate between a haploid gametophyte and a diploid sporophyte generation.", orderIndex: 5 },
  { id: "neet-biology-plant-kingdom-q07", topicId: "neet-biology-plant-kingdom", text: "Red algae owe their colour to the pigment:", optionA: "Chlorophyll a only", optionB: "Phycoerythrin", optionC: "Carotene", optionD: "Xanthophyll", correctOption: "B", explanation: "The red pigment phycoerythrin gives Rhodophyceae (red algae) their colour.", orderIndex: 6 },
  { id: "neet-biology-plant-kingdom-q08", topicId: "neet-biology-plant-kingdom", text: "In pteridophytes, the dominant phase is the:", optionA: "Gametophyte", optionB: "Sporophyte", optionC: "Zygote", optionD: "Spore", correctOption: "B", explanation: "In ferns and other pteridophytes the diploid sporophyte is the main, dominant plant body.", orderIndex: 7 },
  { id: "neet-biology-plant-kingdom-q09", topicId: "neet-biology-plant-kingdom", text: "Which of these is a gymnosperm?", optionA: "Mango", optionB: "Pinus (pine)", optionC: "Fern", optionD: "Moss", correctOption: "B", explanation: "Pinus is a conifer, a classic gymnosperm bearing naked seeds in cones.", orderIndex: 8 },
  { id: "neet-biology-plant-kingdom-q10", topicId: "neet-biology-plant-kingdom", text: "Angiosperms are divided into two classes based on the number of:", optionA: "Petals", optionB: "Cotyledons (monocots and dicots)", optionC: "Roots", optionD: "Stamens", correctOption: "B", explanation: "Angiosperms are split into monocotyledons (one cotyledon) and dicotyledons (two).", orderIndex: 9 },
  { id: "neet-biology-plant-kingdom-q11", topicId: "neet-biology-plant-kingdom", text: "The reserve food material commonly stored in brown algae is:", optionA: "Starch", optionB: "Laminarin and mannitol", optionC: "Glycogen", optionD: "Cellulose", correctOption: "B", explanation: "Brown algae (Phaeophyceae) store food as laminarin and mannitol.", orderIndex: 10 },
  { id: "neet-biology-plant-kingdom-q12", topicId: "neet-biology-plant-kingdom", text: "Ferns reproduce by means of:", optionA: "Seeds", optionB: "Spores", optionC: "Flowers", optionD: "Fruits", correctOption: "B", explanation: "Pteridophytes like ferns reproduce by spores borne on the underside of fronds.", orderIndex: 11 },

  // ── New topic: Animal Kingdom ──
  { id: "neet-biology-animal-kingdom-q01", topicId: "neet-biology-animal-kingdom", text: "The largest animal phylum, characterised by jointed appendages, is:", optionA: "Chordata", optionB: "Arthropoda", optionC: "Mollusca", optionD: "Annelida", correctOption: "B", explanation: "Arthropoda (insects, crustaceans, etc.) is the largest phylum, with jointed legs and an exoskeleton.", orderIndex: 0 },
  { id: "neet-biology-animal-kingdom-q02", topicId: "neet-biology-animal-kingdom", text: "The presence of a notochord at some stage of life is characteristic of:", optionA: "Porifera", optionB: "Chordata", optionC: "Cnidaria", optionD: "Arthropoda", correctOption: "B", explanation: "Chordates possess a notochord, dorsal hollow nerve cord, and pharyngeal slits.", orderIndex: 1 },
  { id: "neet-biology-animal-kingdom-q03", topicId: "neet-biology-animal-kingdom", text: "Sponges (Porifera) have a body organisation at the level of:", optionA: "Organ system", optionB: "Cellular level", optionC: "Organ level", optionD: "Tissue level", correctOption: "B", explanation: "Poriferans show only cellular-level organisation with a canal system.", orderIndex: 2 },
  { id: "neet-biology-animal-kingdom-q04", topicId: "neet-biology-animal-kingdom", text: "Stinging cells (nematocysts) are characteristic of the phylum:", optionA: "Cnidaria (Coelenterata)", optionB: "Platyhelminthes", optionC: "Mollusca", optionD: "Echinodermata", correctOption: "A", explanation: "Cnidarians (Hydra, jellyfish) have cnidoblasts with stinging nematocysts.", orderIndex: 3 },
  { id: "neet-biology-animal-kingdom-q05", topicId: "neet-biology-animal-kingdom", text: "The water vascular system is a unique feature of:", optionA: "Annelida", optionB: "Echinodermata", optionC: "Mollusca", optionD: "Arthropoda", correctOption: "B", explanation: "Echinoderms (starfish) have a water vascular system with tube feet for locomotion.", orderIndex: 4 },
  { id: "neet-biology-animal-kingdom-q06", topicId: "neet-biology-animal-kingdom", text: "Flatworms belong to the phylum:", optionA: "Aschelminthes", optionB: "Platyhelminthes", optionC: "Annelida", optionD: "Nematoda", correctOption: "B", explanation: "Platyhelminthes are dorsoventrally flattened, acoelomate worms (e.g., Planaria, tapeworm).", orderIndex: 5 },
  { id: "neet-biology-animal-kingdom-q07", topicId: "neet-biology-animal-kingdom", text: "Metameric segmentation (true segmentation) is first seen in:", optionA: "Annelida", optionB: "Porifera", optionC: "Cnidaria", optionD: "Protozoa", correctOption: "A", explanation: "Annelids (earthworm, leech) show true metameric segmentation of the body.", orderIndex: 6 },
  { id: "neet-biology-animal-kingdom-q08", topicId: "neet-biology-animal-kingdom", text: "Radial symmetry is characteristic of adult:", optionA: "Humans", optionB: "Echinoderms and cnidarians", optionC: "Insects", optionD: "Earthworms", correctOption: "B", explanation: "Cnidarians and adult echinoderms show radial symmetry; most higher animals are bilateral.", orderIndex: 7 },
  { id: "neet-biology-animal-kingdom-q09", topicId: "neet-biology-animal-kingdom", text: "Animals having a body cavity lined by mesoderm are called:", optionA: "Acoelomates", optionB: "Coelomates", optionC: "Pseudocoelomates", optionD: "Diploblastic", correctOption: "B", explanation: "Coelomates have a true coelom fully lined by mesoderm.", orderIndex: 8 },
  { id: "neet-biology-animal-kingdom-q10", topicId: "neet-biology-animal-kingdom", text: "Which class of vertebrates has a three-chambered heart (in adults, except crocodiles)?", optionA: "Mammalia", optionB: "Reptilia", optionC: "Aves", optionD: "Amphibia and Reptilia", correctOption: "D", explanation: "Amphibians and most reptiles have a three-chambered heart; birds and mammals have four.", orderIndex: 9 },
  { id: "neet-biology-animal-kingdom-q11", topicId: "neet-biology-animal-kingdom", text: "Presence of feathers and a four-chambered heart identifies the class:", optionA: "Aves (birds)", optionB: "Reptilia", optionC: "Amphibia", optionD: "Pisces", correctOption: "A", explanation: "Birds (Aves) are feathered, warm-blooded vertebrates with a four-chambered heart.", orderIndex: 10 },
  { id: "neet-biology-animal-kingdom-q12", topicId: "neet-biology-animal-kingdom", text: "Mammals are characterised by the presence of:", optionA: "Feathers", optionB: "Mammary glands and hair", optionC: "Scales only", optionD: "Gills throughout life", correctOption: "B", explanation: "Mammals have mammary glands (to nourish young) and body hair.", orderIndex: 11 },

  // ── New topic: Morphology of Flowering Plants ──
  { id: "neet-biology-morphology-flowering-plants-q01", topicId: "neet-biology-morphology-flowering-plants", text: "The tap root system is characteristic of:", optionA: "Monocots", optionB: "Dicots", optionC: "Ferns", optionD: "Mosses", correctOption: "B", explanation: "Dicots typically have a tap root system; monocots have a fibrous root system.", orderIndex: 0 },
  { id: "neet-biology-morphology-flowering-plants-q02", topicId: "neet-biology-morphology-flowering-plants", text: "Parallel venation in leaves is typical of:", optionA: "Dicots", optionB: "Monocots", optionC: "Gymnosperms", optionD: "Algae", correctOption: "B", explanation: "Monocot leaves show parallel venation; dicots show reticulate venation.", orderIndex: 1 },
  { id: "neet-biology-morphology-flowering-plants-q03", topicId: "neet-biology-morphology-flowering-plants", text: "The green, leaf-like outermost floral whorl is the:", optionA: "Corolla", optionB: "Calyx (sepals)", optionC: "Androecium", optionD: "Gynoecium", correctOption: "B", explanation: "The calyx, made of sepals, is the outermost protective whorl of a flower.", orderIndex: 2 },
  { id: "neet-biology-morphology-flowering-plants-q04", topicId: "neet-biology-morphology-flowering-plants", text: "The male reproductive part of a flower is the:", optionA: "Gynoecium", optionB: "Androecium (stamens)", optionC: "Calyx", optionD: "Corolla", correctOption: "B", explanation: "The androecium consists of stamens, each with an anther and filament.", orderIndex: 3 },
  { id: "neet-biology-morphology-flowering-plants-q05", topicId: "neet-biology-morphology-flowering-plants", text: "Placentation where ovules are borne on the central axis of a multi-chambered ovary is:", optionA: "Marginal", optionB: "Axile", optionC: "Parietal", optionD: "Free central", correctOption: "B", explanation: "Axile placentation has ovules attached to a central axis in a septate ovary (e.g., tomato).", orderIndex: 4 },
  { id: "neet-biology-morphology-flowering-plants-q06", topicId: "neet-biology-morphology-flowering-plants", text: "An inflorescence with the main axis of unlimited growth and flowers borne laterally is:", optionA: "Cymose", optionB: "Racemose", optionC: "Solitary", optionD: "Compound", correctOption: "B", explanation: "In racemose inflorescences the main axis grows indefinitely; flowers open bottom-up.", orderIndex: 5 },
  { id: "neet-biology-morphology-flowering-plants-q07", topicId: "neet-biology-morphology-flowering-plants", text: "The pea plant (Pisum) belongs to which family, noted for its typical flower?", optionA: "Solanaceae", optionB: "Fabaceae (Leguminosae)", optionC: "Liliaceae", optionD: "Poaceae", correctOption: "B", explanation: "Pea is a member of Fabaceae, with characteristic papilionaceous flowers and pod fruits.", orderIndex: 6 },
  { id: "neet-biology-morphology-flowering-plants-q08", topicId: "neet-biology-morphology-flowering-plants", text: "The edible part of a mango fruit develops from the:", optionA: "Ovule", optionB: "Mesocarp of the pericarp", optionC: "Sepals", optionD: "Anther", correctOption: "B", explanation: "In a mango (a drupe) the fleshy edible portion is the mesocarp of the pericarp.", orderIndex: 7 },
  { id: "neet-biology-morphology-flowering-plants-q09", topicId: "neet-biology-morphology-flowering-plants", text: "A modified underground stem for storage, as in potato, is a:", optionA: "Tuber", optionB: "Tap root", optionC: "Rhizoid", optionD: "Corm-less bulb", correctOption: "A", explanation: "A potato is a stem tuber, an underground stem modification with 'eyes' (buds).", orderIndex: 8 },
  { id: "neet-biology-morphology-flowering-plants-q10", topicId: "neet-biology-morphology-flowering-plants", text: "The arrangement of leaves on a stem is called:", optionA: "Aestivation", optionB: "Phyllotaxy", optionC: "Placentation", optionD: "Venation", correctOption: "B", explanation: "Phyllotaxy is the pattern of leaf arrangement (alternate, opposite, whorled).", orderIndex: 9 },
  { id: "neet-biology-morphology-flowering-plants-q11", topicId: "neet-biology-morphology-flowering-plants", text: "A flower with both androecium and gynoecium is called:", optionA: "Unisexual", optionB: "Bisexual (perfect)", optionC: "Sterile", optionD: "Neuter", correctOption: "B", explanation: "A bisexual flower contains both stamens and carpels.", orderIndex: 10 },
  { id: "neet-biology-morphology-flowering-plants-q12", topicId: "neet-biology-morphology-flowering-plants", text: "Aestivation refers to the arrangement of:", optionA: "Leaves on a stem", optionB: "Sepals/petals in a floral bud", optionC: "Ovules in an ovary", optionD: "Roots in soil", correctOption: "B", explanation: "Aestivation is the mode of arrangement of sepals or petals in a floral bud.", orderIndex: 11 },

  // ── New topic: Anatomy of Flowering Plants ──
  { id: "neet-biology-anatomy-flowering-plants-q01", topicId: "neet-biology-anatomy-flowering-plants", text: "Which tissue conducts food in plants?", optionA: "Xylem", optionB: "Phloem", optionC: "Collenchyma", optionD: "Sclerenchyma", correctOption: "B", explanation: "Phloem (sieve tubes and companion cells) transports food from source to sink.", orderIndex: 0 },
  { id: "neet-biology-anatomy-flowering-plants-q02", topicId: "neet-biology-anatomy-flowering-plants", text: "The dead, lignified supporting tissue in plants is:", optionA: "Parenchyma", optionB: "Sclerenchyma", optionC: "Collenchyma", optionD: "Epidermis", correctOption: "B", explanation: "Sclerenchyma cells are dead with thick lignified walls, providing mechanical support.", orderIndex: 1 },
  { id: "neet-biology-anatomy-flowering-plants-q03", topicId: "neet-biology-anatomy-flowering-plants", text: "Secondary growth in dicot stems arises from the:", optionA: "Apical meristem", optionB: "Vascular cambium", optionC: "Ground tissue", optionD: "Epidermis", correctOption: "B", explanation: "The vascular cambium produces secondary xylem and phloem, increasing girth.", orderIndex: 2 },
  { id: "neet-biology-anatomy-flowering-plants-q04", topicId: "neet-biology-anatomy-flowering-plants", text: "In monocot stems, the vascular bundles are:", optionA: "Arranged in a ring", optionB: "Scattered", optionC: "Absent", optionD: "In the pith only", correctOption: "B", explanation: "Monocot stems have scattered vascular bundles; dicot stems have them in a ring.", orderIndex: 3 },
  { id: "neet-biology-anatomy-flowering-plants-q05", topicId: "neet-biology-anatomy-flowering-plants", text: "Water-conducting elements found only in angiosperms are:", optionA: "Tracheids", optionB: "Vessels", optionC: "Sieve tubes", optionD: "Companion cells", correctOption: "B", explanation: "Vessels (efficient water conduits) are characteristic of angiosperm xylem.", orderIndex: 4 },
  { id: "neet-biology-anatomy-flowering-plants-q06", topicId: "neet-biology-anatomy-flowering-plants", text: "Annual rings in a tree trunk are due to:", optionA: "Activity of the vascular cambium varying with seasons", optionB: "Leaf fall", optionC: "Root growth", optionD: "Flowering", correctOption: "A", explanation: "Seasonal differences in cambial activity produce distinct early and late wood — annual rings.", orderIndex: 5 },
  { id: "neet-biology-anatomy-flowering-plants-q07", topicId: "neet-biology-anatomy-flowering-plants", text: "Guard cells regulate the opening and closing of:", optionA: "Lenticels", optionB: "Stomata", optionC: "Vessels", optionD: "Sieve pores", correctOption: "B", explanation: "Turgid guard cells open the stomatal pore for gas exchange and transpiration.", orderIndex: 6 },
  { id: "neet-biology-anatomy-flowering-plants-q08", topicId: "neet-biology-anatomy-flowering-plants", text: "The living companion cells are associated with:", optionA: "Vessels", optionB: "Sieve tube elements", optionC: "Tracheids", optionD: "Fibres", correctOption: "B", explanation: "Companion cells support the enucleate sieve tube elements in phloem.", orderIndex: 7 },
  { id: "neet-biology-anatomy-flowering-plants-q09", topicId: "neet-biology-anatomy-flowering-plants", text: "Collenchyma provides support especially in:", optionA: "Woody stems", optionB: "Young, growing stems and petioles", optionC: "Roots only", optionD: "Dead tissues", correctOption: "B", explanation: "Collenchyma, with thickened corners, gives flexible support to young growing organs.", orderIndex: 8 },
  { id: "neet-biology-anatomy-flowering-plants-q10", topicId: "neet-biology-anatomy-flowering-plants", text: "The outermost protective tissue of the primary plant body is the:", optionA: "Epidermis", optionB: "Endodermis", optionC: "Pericycle", optionD: "Cortex", correctOption: "A", explanation: "The epidermis is the outer covering, often coated with a waxy cuticle.", orderIndex: 9 },
  { id: "neet-biology-anatomy-flowering-plants-q11", topicId: "neet-biology-anatomy-flowering-plants", text: "The Casparian strips are found in the:", optionA: "Epidermis", optionB: "Endodermis of the root", optionC: "Phloem", optionD: "Cortex", correctOption: "B", explanation: "The endodermal Casparian strips (suberin) regulate water entry into the vascular cylinder.", orderIndex: 10 },
  { id: "neet-biology-anatomy-flowering-plants-q12", topicId: "neet-biology-anatomy-flowering-plants", text: "Meristematic tissue is characterised by cells that:", optionA: "Are dead and thick-walled", optionB: "Actively divide", optionC: "Store food only", optionD: "Conduct water", correctOption: "B", explanation: "Meristems are regions of actively dividing cells responsible for growth.", orderIndex: 11 },

  // ── New topic: Structural Organisation in Animals ──
  { id: "neet-biology-structural-organisation-animals-q01", topicId: "neet-biology-structural-organisation-animals", text: "The tissue that lines body cavities and covers surfaces is:", optionA: "Connective tissue", optionB: "Epithelial tissue", optionC: "Muscular tissue", optionD: "Neural tissue", correctOption: "B", explanation: "Epithelial tissue forms coverings and linings and rests on a basement membrane.", orderIndex: 0 },
  { id: "neet-biology-structural-organisation-animals-q02", topicId: "neet-biology-structural-organisation-animals", text: "Which tissue has an abundant extracellular matrix?", optionA: "Epithelial", optionB: "Connective", optionC: "Neural", optionD: "Squamous", correctOption: "B", explanation: "Connective tissues (blood, bone, cartilage) are defined by their extensive matrix.", orderIndex: 1 },
  { id: "neet-biology-structural-organisation-animals-q03", topicId: "neet-biology-structural-organisation-animals", text: "Tendons, which connect muscle to bone, are made of:", optionA: "Cardiac muscle", optionB: "Dense regular connective tissue", optionC: "Adipose tissue", optionD: "Epithelium", correctOption: "B", explanation: "Tendons are dense regular connective tissue rich in collagen fibres.", orderIndex: 2 },
  { id: "neet-biology-structural-organisation-animals-q04", topicId: "neet-biology-structural-organisation-animals", text: "The junction that prevents leakage of substances between cells is the:", optionA: "Gap junction", optionB: "Tight junction", optionC: "Adhering junction", optionD: "Synapse", correctOption: "B", explanation: "Tight junctions seal adjacent cells, stopping substances from leaking between them.", orderIndex: 3 },
  { id: "neet-biology-structural-organisation-animals-q05", topicId: "neet-biology-structural-organisation-animals", text: "Adipose tissue is specialised to store:", optionA: "Water", optionB: "Fat", optionC: "Glycogen only", optionD: "Minerals", correctOption: "B", explanation: "Adipose is a loose connective tissue storing fat for energy and insulation.", orderIndex: 4 },
  { id: "neet-biology-structural-organisation-animals-q06", topicId: "neet-biology-structural-organisation-animals", text: "Gap junctions function to:", optionA: "Seal cells together", optionB: "Allow rapid communication between adjacent cells", optionC: "Anchor cells to matrix", optionD: "Secrete enzymes", correctOption: "B", explanation: "Gap junctions form channels allowing ions and small molecules to pass between cells.", orderIndex: 5 },
  { id: "neet-biology-structural-organisation-animals-q07", topicId: "neet-biology-structural-organisation-animals", text: "Which muscle type is branched and shows intercalated discs?", optionA: "Skeletal", optionB: "Cardiac", optionC: "Smooth", optionD: "Visceral", correctOption: "B", explanation: "Cardiac muscle cells are branched and joined by intercalated discs for synchronised contraction.", orderIndex: 6 },
  { id: "neet-biology-structural-organisation-animals-q08", topicId: "neet-biology-structural-organisation-animals", text: "Neuroglia are cells that:", optionA: "Transmit impulses", optionB: "Support and protect neurons", optionC: "Store fat", optionD: "Secrete hormones", correctOption: "B", explanation: "Neuroglial cells provide structural and metabolic support to neurons in neural tissue.", orderIndex: 7 },
  { id: "neet-biology-structural-organisation-animals-q09", topicId: "neet-biology-structural-organisation-animals", text: "Cartilage differs from bone in that its matrix is:", optionA: "Calcified and hard", optionB: "Flexible and non-calcified (chondroitin)", optionC: "Fluid", optionD: "Absent", correctOption: "B", explanation: "Cartilage has a pliable, non-mineralised matrix, unlike the calcified matrix of bone.", orderIndex: 8 },
  { id: "neet-biology-structural-organisation-animals-q10", topicId: "neet-biology-structural-organisation-animals", text: "In the earthworm, locomotion is aided by:", optionA: "Tube feet", optionB: "Setae (chaetae)", optionC: "Wings", optionD: "Fins", correctOption: "B", explanation: "Earthworms use S-shaped setae and muscle contraction to move through soil.", orderIndex: 9 },
  { id: "neet-biology-structural-organisation-animals-q11", topicId: "neet-biology-structural-organisation-animals", text: "The cockroach has an open circulatory system in which blood is called:", optionA: "Plasma", optionB: "Haemolymph", optionC: "Lymph", optionD: "Serum", correctOption: "B", explanation: "Insects have haemolymph flowing through body spaces (haemocoel) in an open system.", orderIndex: 10 },
  { id: "neet-biology-structural-organisation-animals-q12", topicId: "neet-biology-structural-organisation-animals", text: "Glandular epithelium is specialised for:", optionA: "Contraction", optionB: "Secretion", optionC: "Impulse conduction", optionD: "Storage of fat", correctOption: "B", explanation: "Glandular epithelium is modified to secrete substances (exocrine or endocrine).", orderIndex: 11 },

  // ── New topic: Transport in Plants ──
  { id: "neet-biology-transport-in-plants-q01", topicId: "neet-biology-transport-in-plants", text: "The upward movement of water in xylem is best explained by the:", optionA: "Root pressure theory alone", optionB: "Transpiration pull–cohesion–tension theory", optionC: "Active transport theory", optionD: "Imbibition theory", correctOption: "B", explanation: "Transpiration creates tension transmitted through cohesive water columns, pulling water up.", orderIndex: 0 },
  { id: "neet-biology-transport-in-plants-q02", topicId: "neet-biology-transport-in-plants", text: "The loss of water vapour from aerial plant parts is called:", optionA: "Guttation", optionB: "Transpiration", optionC: "Osmosis", optionD: "Imbibition", correctOption: "B", explanation: "Transpiration is water loss as vapour, mostly through stomata.", orderIndex: 1 },
  { id: "neet-biology-transport-in-plants-q03", topicId: "neet-biology-transport-in-plants", text: "Water potential of pure water at standard conditions is:", optionA: "Positive", optionB: "Zero", optionC: "Always negative", optionD: "Infinite", correctOption: "B", explanation: "Pure water is assigned a water potential of zero; adding solutes makes it negative.", orderIndex: 2 },
  { id: "neet-biology-transport-in-plants-q04", topicId: "neet-biology-transport-in-plants", text: "Phloem transport (translocation) is explained by the:", optionA: "Pressure-flow (mass-flow) hypothesis", optionB: "Cohesion-tension theory", optionC: "Root pressure", optionD: "Diffusion only", correctOption: "A", explanation: "The pressure-flow hypothesis explains sugar movement from source to sink in phloem.", orderIndex: 3 },
  { id: "neet-biology-transport-in-plants-q05", topicId: "neet-biology-transport-in-plants", text: "Stomata generally open when the guard cells become:", optionA: "Flaccid", optionB: "Turgid", optionC: "Plasmolysed", optionD: "Dead", correctOption: "B", explanation: "Turgid guard cells bow apart, opening the stomatal pore.", orderIndex: 4 },
  { id: "neet-biology-transport-in-plants-q06", topicId: "neet-biology-transport-in-plants", text: "Movement of water molecules into a cell down a water-potential gradient is:", optionA: "Active transport", optionB: "Osmosis", optionC: "Translocation", optionD: "Transpiration", correctOption: "B", explanation: "Osmosis is the passive movement of water across a semipermeable membrane down its potential gradient.", orderIndex: 5 },
  { id: "neet-biology-transport-in-plants-q07", topicId: "neet-biology-transport-in-plants", text: "Guttation, the loss of liquid water from leaf margins, is driven mainly by:", optionA: "Transpiration pull", optionB: "Root pressure", optionC: "Photosynthesis", optionD: "Wind", correctOption: "B", explanation: "Root pressure forces water out through hydathodes as droplets (guttation), typically at night.", orderIndex: 6 },
  { id: "neet-biology-transport-in-plants-q08", topicId: "neet-biology-transport-in-plants", text: "Active transport of solutes across membranes requires:", optionA: "ATP energy", optionB: "No energy", optionC: "Only a concentration gradient", optionD: "Only water", correctOption: "A", explanation: "Active transport moves solutes against a gradient using energy (ATP) and carrier proteins.", orderIndex: 7 },
  { id: "neet-biology-transport-in-plants-q09", topicId: "neet-biology-transport-in-plants", text: "The swelling of dry seeds when placed in water is an example of:", optionA: "Osmosis", optionB: "Imbibition", optionC: "Transpiration", optionD: "Guttation", correctOption: "B", explanation: "Imbibition is the adsorption of water by hydrophilic colloids like seed proteins/starch.", orderIndex: 8 },
  { id: "neet-biology-transport-in-plants-q10", topicId: "neet-biology-transport-in-plants", text: "The apoplast pathway of water movement is through:", optionA: "The cytoplasm and plasmodesmata", optionB: "Cell walls and intercellular spaces", optionC: "The phloem", optionD: "The vacuoles only", correctOption: "B", explanation: "The apoplast is the non-living continuum of cell walls and spaces, offering little resistance.", orderIndex: 9 },
  { id: "neet-biology-transport-in-plants-q11", topicId: "neet-biology-transport-in-plants", text: "Adding solute to pure water changes its water potential to become:", optionA: "More positive", optionB: "More negative", optionC: "Unchanged", optionD: "Zero exactly", correctOption: "B", explanation: "Solutes lower (make more negative) the water potential via the solute potential term.", orderIndex: 10 },
  { id: "neet-biology-transport-in-plants-q12", topicId: "neet-biology-transport-in-plants", text: "Most transpiration in plants occurs through the:", optionA: "Cuticle", optionB: "Stomata", optionC: "Lenticels", optionD: "Roots", correctOption: "B", explanation: "The bulk of transpiration is stomatal, through the pores on leaf surfaces.", orderIndex: 11 },

  // ── New topic: Mineral Nutrition ──
  { id: "neet-biology-mineral-nutrition-q01", topicId: "neet-biology-mineral-nutrition", text: "Elements required by plants in large amounts are called:", optionA: "Micronutrients", optionB: "Macronutrients", optionC: "Trace elements", optionD: "Beneficial elements", correctOption: "B", explanation: "Macronutrients (C, H, O, N, P, K, Ca, Mg, S) are needed in relatively large quantities.", orderIndex: 0 },
  { id: "neet-biology-mineral-nutrition-q02", topicId: "neet-biology-mineral-nutrition", text: "Biological nitrogen fixation by Rhizobium occurs in the:", optionA: "Leaves", optionB: "Root nodules of legumes", optionC: "Stem", optionD: "Flowers", correctOption: "B", explanation: "Rhizobium fixes atmospheric N₂ symbiotically inside legume root nodules.", orderIndex: 1 },
  { id: "neet-biology-mineral-nutrition-q03", topicId: "neet-biology-mineral-nutrition", text: "The enzyme responsible for biological nitrogen fixation is:", optionA: "Nitrogenase", optionB: "Amylase", optionC: "Catalase", optionD: "RuBisCO", correctOption: "A", explanation: "Nitrogenase reduces atmospheric N₂ to ammonia; it is highly sensitive to oxygen.", orderIndex: 2 },
  { id: "neet-biology-mineral-nutrition-q04", topicId: "neet-biology-mineral-nutrition", text: "Leghaemoglobin in root nodules functions to:", optionA: "Fix carbon", optionB: "Scavenge oxygen (protect nitrogenase)", optionC: "Store starch", optionD: "Transport water", correctOption: "B", explanation: "Leghaemoglobin binds oxygen, protecting the oxygen-sensitive nitrogenase enzyme.", orderIndex: 3 },
  { id: "neet-biology-mineral-nutrition-q05", topicId: "neet-biology-mineral-nutrition", text: "Which is a micronutrient for plants?", optionA: "Nitrogen", optionB: "Zinc", optionC: "Potassium", optionD: "Calcium", correctOption: "B", explanation: "Zinc (like Fe, Mn, Cu, B, Mo) is a micronutrient needed in trace amounts.", orderIndex: 4 },
  { id: "neet-biology-mineral-nutrition-q06", topicId: "neet-biology-mineral-nutrition", text: "Growing plants in a nutrient solution without soil is called:", optionA: "Hydroponics", optionB: "Photoperiodism", optionC: "Vernalisation", optionD: "Grafting", correctOption: "A", explanation: "Hydroponics is soil-less culture in a defined nutrient solution.", orderIndex: 5 },
  { id: "neet-biology-mineral-nutrition-q07", topicId: "neet-biology-mineral-nutrition", text: "Deficiency of nitrogen causes:", optionA: "Chlorosis (yellowing), especially in older leaves", optionB: "Increased flowering", optionC: "Root thickening", optionD: "No effect", correctOption: "A", explanation: "Nitrogen is mobile, so its deficiency yellows older leaves first (chlorosis).", orderIndex: 6 },
  { id: "neet-biology-mineral-nutrition-q08", topicId: "neet-biology-mineral-nutrition", text: "An essential element must be:", optionA: "Required for a plant's normal life cycle and irreplaceable", optionB: "Present in soil only", optionC: "A heavy metal", optionD: "Toxic", correctOption: "A", explanation: "An essential element is indispensable and cannot be replaced by another for the plant's life cycle.", orderIndex: 7 },
  { id: "neet-biology-mineral-nutrition-q09", topicId: "neet-biology-mineral-nutrition", text: "Magnesium is important in plants because it is a component of:", optionA: "Chlorophyll", optionB: "Cellulose", optionC: "DNA", optionD: "Starch", correctOption: "A", explanation: "Magnesium is the central atom of the chlorophyll molecule and activates enzymes.", orderIndex: 8 },
  { id: "neet-biology-mineral-nutrition-q10", topicId: "neet-biology-mineral-nutrition", text: "Free-living nitrogen-fixing bacteria in soil include:", optionA: "Azotobacter", optionB: "Lactobacillus", optionC: "E. coli", optionD: "Salmonella", correctOption: "A", explanation: "Azotobacter (aerobic) and Clostridium (anaerobic) fix nitrogen free-living in soil.", orderIndex: 9 },
  { id: "neet-biology-mineral-nutrition-q11", topicId: "neet-biology-mineral-nutrition", text: "The conversion of ammonia to nitrate by soil bacteria is called:", optionA: "Nitrification", optionB: "Denitrification", optionC: "Ammonification", optionD: "Fixation", correctOption: "A", explanation: "Nitrifying bacteria (Nitrosomonas, Nitrobacter) convert NH₃ → nitrite → nitrate.", orderIndex: 10 },
  { id: "neet-biology-mineral-nutrition-q12", topicId: "neet-biology-mineral-nutrition", text: "Denitrification returns nitrogen to the atmosphere by converting:", optionA: "Nitrate to N₂ gas", optionB: "N₂ to ammonia", optionC: "Ammonia to nitrate", optionD: "Protein to amino acids", correctOption: "A", explanation: "Denitrifying bacteria reduce nitrate to gaseous N₂, completing the nitrogen cycle.", orderIndex: 11 },

  // ── New topic: Respiration in Plants ──
  { id: "neet-biology-respiration-in-plants-q01", topicId: "neet-biology-respiration-in-plants", text: "Glycolysis takes place in the:", optionA: "Mitochondrial matrix", optionB: "Cytoplasm", optionC: "Chloroplast", optionD: "Nucleus", correctOption: "B", explanation: "Glycolysis occurs in the cytoplasm and splits glucose into two pyruvate molecules.", orderIndex: 0 },
  { id: "neet-biology-respiration-in-plants-q02", topicId: "neet-biology-respiration-in-plants", text: "The Krebs cycle occurs in the:", optionA: "Cytoplasm", optionB: "Mitochondrial matrix", optionC: "Thylakoid", optionD: "Ribosome", correctOption: "B", explanation: "The TCA (Krebs) cycle takes place in the mitochondrial matrix.", orderIndex: 1 },
  { id: "neet-biology-respiration-in-plants-q03", topicId: "neet-biology-respiration-in-plants", text: "The net ATP yield from glycolysis (per glucose) is:", optionA: "2 ATP", optionB: "36 ATP", optionC: "4 ATP", optionD: "38 ATP", correctOption: "A", explanation: "Glycolysis produces 4 ATP but uses 2, giving a net of 2 ATP (plus 2 NADH).", orderIndex: 2 },
  { id: "neet-biology-respiration-in-plants-q04", topicId: "neet-biology-respiration-in-plants", text: "The final electron acceptor in aerobic respiration is:", optionA: "Water", optionB: "Oxygen", optionC: "NAD⁺", optionD: "Carbon dioxide", correctOption: "B", explanation: "Oxygen accepts electrons at the end of the electron transport chain, forming water.", orderIndex: 3 },
  { id: "neet-biology-respiration-in-plants-q05", topicId: "neet-biology-respiration-in-plants", text: "In the absence of oxygen, yeast carries out fermentation producing:", optionA: "Lactic acid", optionB: "Ethanol and CO₂", optionC: "Water only", optionD: "Glucose", correctOption: "B", explanation: "Alcoholic fermentation in yeast converts pyruvate to ethanol and carbon dioxide.", orderIndex: 4 },
  { id: "neet-biology-respiration-in-plants-q06", topicId: "neet-biology-respiration-in-plants", text: "The respiratory quotient (RQ) for carbohydrates is:", optionA: "1", optionB: "0.7", optionC: "Greater than 1", optionD: "0", correctOption: "A", explanation: "For carbohydrate oxidation, CO₂ released equals O₂ consumed, so RQ = 1.", orderIndex: 5 },
  { id: "neet-biology-respiration-in-plants-q07", topicId: "neet-biology-respiration-in-plants", text: "Oxidative phosphorylation (ATP synthesis using the ETC) occurs on the:", optionA: "Inner mitochondrial membrane", optionB: "Cytoplasm", optionC: "Outer membrane", optionD: "Ribosomes", correctOption: "A", explanation: "The electron transport chain and ATP synthase are on the inner mitochondrial membrane.", orderIndex: 6 },
  { id: "neet-biology-respiration-in-plants-q08", topicId: "neet-biology-respiration-in-plants", text: "Complete aerobic oxidation of one glucose molecule yields approximately:", optionA: "2 ATP", optionB: "36–38 ATP", optionC: "12 ATP", optionD: "100 ATP", correctOption: "B", explanation: "Aerobic respiration of glucose yields about 36–38 ATP in total.", orderIndex: 7 },
  { id: "neet-biology-respiration-in-plants-q09", topicId: "neet-biology-respiration-in-plants", text: "The connecting link between glycolysis and the Krebs cycle is the formation of:", optionA: "Lactic acid", optionB: "Acetyl-CoA", optionC: "Ethanol", optionD: "Glucose", correctOption: "B", explanation: "Pyruvate is oxidatively decarboxylated to acetyl-CoA, which enters the Krebs cycle.", orderIndex: 8 },
  { id: "neet-biology-respiration-in-plants-q10", topicId: "neet-biology-respiration-in-plants", text: "An RQ less than 1 indicates the respiratory substrate is a:", optionA: "Carbohydrate", optionB: "Fat", optionC: "Organic acid", optionD: "Protein only", correctOption: "B", explanation: "Fats consume more oxygen relative to CO₂ released, giving RQ < 1 (about 0.7).", orderIndex: 9 },
  { id: "neet-biology-respiration-in-plants-q11", topicId: "neet-biology-respiration-in-plants", text: "In muscle cells under oxygen shortage, glucose is converted to:", optionA: "Ethanol", optionB: "Lactic acid", optionC: "Acetyl-CoA", optionD: "Starch", correctOption: "B", explanation: "Anaerobic respiration in animal muscle produces lactic acid, causing fatigue.", orderIndex: 10 },
  { id: "neet-biology-respiration-in-plants-q12", topicId: "neet-biology-respiration-in-plants", text: "Amphibolic pathway means the respiratory pathway is involved in:", optionA: "Only breakdown (catabolism)", optionB: "Both breakdown and synthesis", optionC: "Only synthesis (anabolism)", optionD: "Neither", correctOption: "B", explanation: "Respiration is amphibolic: its intermediates serve both catabolic and anabolic (biosynthetic) roles.", orderIndex: 11 },

  // ── New topic: Plant Growth & Development ──
  { id: "neet-biology-plant-growth-development-q01", topicId: "neet-biology-plant-growth-development", text: "The plant hormone responsible for apical dominance is:", optionA: "Auxin", optionB: "Ethylene", optionC: "Abscisic acid", optionD: "Cytokinin", correctOption: "A", explanation: "Auxin produced at the shoot tip suppresses growth of lateral buds (apical dominance).", orderIndex: 0 },
  { id: "neet-biology-plant-growth-development-q02", topicId: "neet-biology-plant-growth-development", text: "Which hormone promotes fruit ripening and is a gas?", optionA: "Gibberellin", optionB: "Ethylene", optionC: "Auxin", optionD: "Cytokinin", correctOption: "B", explanation: "Ethylene is the gaseous hormone that hastens fruit ripening and senescence.", orderIndex: 1 },
  { id: "neet-biology-plant-growth-development-q03", topicId: "neet-biology-plant-growth-development", text: "The 'stress hormone' that promotes stomatal closure and dormancy is:", optionA: "Auxin", optionB: "Abscisic acid", optionC: "Gibberellin", optionD: "Cytokinin", correctOption: "B", explanation: "Abscisic acid (ABA) closes stomata under water stress and induces bud/seed dormancy.", orderIndex: 2 },
  { id: "neet-biology-plant-growth-development-q04", topicId: "neet-biology-plant-growth-development", text: "Gibberellins are best known for causing:", optionA: "Stem elongation and bolting", optionB: "Stomatal closure", optionC: "Apical dominance", optionD: "Leaf abscission", correctOption: "A", explanation: "Gibberellins promote internode elongation, bolting, and break seed/bud dormancy.", orderIndex: 3 },
  { id: "neet-biology-plant-growth-development-q05", topicId: "neet-biology-plant-growth-development", text: "Cytokinins primarily promote:", optionA: "Cell division and delay senescence", optionB: "Fruit ripening", optionC: "Stomatal closure", optionD: "Root dormancy", correctOption: "A", explanation: "Cytokinins stimulate cytokinesis (cell division) and delay leaf ageing.", orderIndex: 4 },
  { id: "neet-biology-plant-growth-development-q06", topicId: "neet-biology-plant-growth-development", text: "The response of plants to the relative lengths of day and night is:", optionA: "Vernalisation", optionB: "Photoperiodism", optionC: "Phototropism", optionD: "Geotropism", correctOption: "B", explanation: "Photoperiodism is the flowering response to day/night length, sensed via phytochrome.", orderIndex: 5 },
  { id: "neet-biology-plant-growth-development-q07", topicId: "neet-biology-plant-growth-development", text: "The promotion of flowering by exposure to low temperature is called:", optionA: "Photoperiodism", optionB: "Vernalisation", optionC: "Dormancy", optionD: "Etiolation", correctOption: "B", explanation: "Vernalisation is the requirement of a cold period to induce or accelerate flowering.", orderIndex: 6 },
  { id: "neet-biology-plant-growth-development-q08", topicId: "neet-biology-plant-growth-development", text: "The site that perceives the photoperiodic stimulus for flowering is the:", optionA: "Root tip", optionB: "Leaf", optionC: "Flower", optionD: "Seed", correctOption: "B", explanation: "Leaves perceive the day-length signal (via phytochrome) and induce flowering.", orderIndex: 7 },
  { id: "neet-biology-plant-growth-development-q09", topicId: "neet-biology-plant-growth-development", text: "Auxin is commonly used commercially to:", optionA: "Promote rooting in stem cuttings", optionB: "Ripen fruit", optionC: "Close stomata", optionD: "Delay germination", correctOption: "A", explanation: "Auxins (e.g., IBA, NAA) are applied to induce adventitious roots in cuttings.", orderIndex: 8 },
  { id: "neet-biology-plant-growth-development-q10", topicId: "neet-biology-plant-growth-development", text: "Plant growth is described as 'open' because it:", optionA: "Occurs only once", optionB: "Continues throughout life via meristems", optionC: "Stops at maturity", optionD: "Is determinate", correctOption: "B", explanation: "Meristems allow indeterminate (open) growth throughout the plant's life.", orderIndex: 9 },
  { id: "neet-biology-plant-growth-development-q11", topicId: "neet-biology-plant-growth-development", text: "The phase of cell growth where cells enlarge and vacuolate is the:", optionA: "Meristematic phase", optionB: "Elongation phase", optionC: "Maturation phase", optionD: "Dormant phase", correctOption: "B", explanation: "In the elongation phase, cells increase in size with vacuolation and new wall material.", orderIndex: 10 },
  { id: "neet-biology-plant-growth-development-q12", topicId: "neet-biology-plant-growth-development", text: "The pigment that regulates photoperiodic and light responses is:", optionA: "Chlorophyll", optionB: "Phytochrome", optionC: "Carotene", optionD: "Anthocyanin", correctOption: "B", explanation: "Phytochrome perceives red/far-red light to regulate flowering and germination.", orderIndex: 11 },

  // ── New topic: Locomotion & Movement ──
  { id: "neet-biology-locomotion-movement-q01", topicId: "neet-biology-locomotion-movement", text: "The contractile proteins of skeletal muscle are:", optionA: "Actin and myosin", optionB: "Collagen and elastin", optionC: "Keratin and tubulin", optionD: "Albumin and globulin", correctOption: "A", explanation: "Actin (thin) and myosin (thick) filaments slide past each other during contraction.", orderIndex: 0 },
  { id: "neet-biology-locomotion-movement-q02", topicId: "neet-biology-locomotion-movement", text: "According to the sliding filament theory, during contraction:", optionA: "Actin filaments slide over myosin, shortening the sarcomere", optionB: "Filaments themselves shorten", optionC: "Only myosin shortens", optionD: "The A-band shortens", correctOption: "A", explanation: "Thin filaments slide over thick ones; the sarcomere shortens while filament lengths stay constant.", orderIndex: 1 },
  { id: "neet-biology-locomotion-movement-q03", topicId: "neet-biology-locomotion-movement", text: "The ion essential for triggering muscle contraction is:", optionA: "Na⁺", optionB: "Ca²⁺", optionC: "K⁺", optionD: "Cl⁻", correctOption: "B", explanation: "Calcium ions released from the sarcoplasmic reticulum expose actin binding sites for contraction.", orderIndex: 2 },
  { id: "neet-biology-locomotion-movement-q04", topicId: "neet-biology-locomotion-movement", text: "The total number of bones in the adult human skeleton is:", optionA: "206", optionB: "300", optionC: "150", optionD: "246", correctOption: "A", explanation: "The adult human skeleton has 206 bones (axial + appendicular).", orderIndex: 3 },
  { id: "neet-biology-locomotion-movement-q05", topicId: "neet-biology-locomotion-movement", text: "The freely movable joints of the body are called:", optionA: "Fibrous joints", optionB: "Synovial joints", optionC: "Cartilaginous joints", optionD: "Sutures", correctOption: "B", explanation: "Synovial joints (e.g., knee, shoulder) permit free movement with a lubricated cavity.", orderIndex: 4 },
  { id: "neet-biology-locomotion-movement-q06", topicId: "neet-biology-locomotion-movement", text: "During contraction, which region of the sarcomere shortens?", optionA: "A-band", optionB: "I-band and H-zone", optionC: "Myosin filament", optionD: "Z-line thickness", correctOption: "B", explanation: "The I-band and H-zone shorten during contraction; the A-band length remains unchanged.", orderIndex: 5 },
  { id: "neet-biology-locomotion-movement-q07", topicId: "neet-biology-locomotion-movement", text: "The axial skeleton includes the:", optionA: "Limbs and girdles", optionB: "Skull, vertebral column, ribs, and sternum", optionC: "Hands and feet", optionD: "Pelvic girdle only", correctOption: "B", explanation: "The axial skeleton comprises the skull, vertebral column, ribs, and sternum.", orderIndex: 6 },
  { id: "neet-biology-locomotion-movement-q08", topicId: "neet-biology-locomotion-movement", text: "A disorder caused by autoimmune damage at the neuromuscular junction is:", optionA: "Gout", optionB: "Myasthenia gravis", optionC: "Osteoporosis", optionD: "Arthritis", correctOption: "B", explanation: "Myasthenia gravis is autoimmune, causing fatigue and weakness of skeletal muscles.", orderIndex: 7 },
  { id: "neet-biology-locomotion-movement-q09", topicId: "neet-biology-locomotion-movement", text: "The energy currency directly powering muscle contraction is:", optionA: "Glucose", optionB: "ATP", optionC: "Creatine only", optionD: "Fat", correctOption: "B", explanation: "ATP hydrolysis on the myosin head drives the cross-bridge cycle of contraction.", orderIndex: 8 },
  { id: "neet-biology-locomotion-movement-q10", topicId: "neet-biology-locomotion-movement", text: "The proteins that regulate the binding of myosin to actin are:", optionA: "Troponin and tropomyosin", optionB: "Collagen and elastin", optionC: "Albumin and casein", optionD: "Keratin and myoglobin", correctOption: "A", explanation: "Troponin–tropomyosin blocks actin sites until Ca²⁺ binds troponin, allowing contraction.", orderIndex: 9 },
  { id: "neet-biology-locomotion-movement-q11", topicId: "neet-biology-locomotion-movement", text: "Osteoporosis, common in older women, is characterised by:", optionA: "Decreased bone mass and density", optionB: "Increased bone density", optionC: "Joint inflammation", optionD: "Muscle wasting only", correctOption: "A", explanation: "Osteoporosis reduces bone mass (often with reduced oestrogen), raising fracture risk.", orderIndex: 10 },
  { id: "neet-biology-locomotion-movement-q12", topicId: "neet-biology-locomotion-movement", text: "The functional contractile unit of a myofibril, between two Z-lines, is the:", optionA: "Sarcomere", optionB: "Sarcolemma", optionC: "Myofilament", optionD: "Fascicle", correctOption: "A", explanation: "The sarcomere, the region between two Z-lines, is the functional unit of contraction.", orderIndex: 11 },

  // ── New topic: Chemical Coordination & Hormones ──
  { id: "neet-biology-chemical-coordination-hormones-q01", topicId: "neet-biology-chemical-coordination-hormones", text: "The 'master gland' of the endocrine system is the:", optionA: "Thyroid", optionB: "Pituitary", optionC: "Adrenal", optionD: "Pancreas", correctOption: "B", explanation: "The pituitary is called the master gland because it controls other endocrine glands.", orderIndex: 0 },
  { id: "neet-biology-chemical-coordination-hormones-q02", topicId: "neet-biology-chemical-coordination-hormones", text: "The hormone insulin is secreted by which cells?", optionA: "Alpha cells", optionB: "Beta cells of the islets of Langerhans", optionC: "Adrenal cortex", optionD: "Thyroid follicles", correctOption: "B", explanation: "Beta cells of the pancreatic islets secrete insulin, which lowers blood glucose.", orderIndex: 1 },
  { id: "neet-biology-chemical-coordination-hormones-q03", topicId: "neet-biology-chemical-coordination-hormones", text: "Deficiency of iodine leads to under-production of thyroxine and causes:", optionA: "Diabetes", optionB: "Goitre", optionC: "Dwarfism", optionD: "Cretinism only in adults", correctOption: "B", explanation: "Iodine deficiency reduces thyroxine, enlarging the thyroid gland (goitre).", orderIndex: 2 },
  { id: "neet-biology-chemical-coordination-hormones-q04", topicId: "neet-biology-chemical-coordination-hormones", text: "The 'fight or flight' hormone from the adrenal medulla is:", optionA: "Insulin", optionB: "Adrenaline (epinephrine)", optionC: "Thyroxine", optionD: "Parathormone", correctOption: "B", explanation: "Adrenaline prepares the body for emergencies, raising heart rate and blood glucose.", orderIndex: 3 },
  { id: "neet-biology-chemical-coordination-hormones-q05", topicId: "neet-biology-chemical-coordination-hormones", text: "The hormone raising blood calcium levels is:", optionA: "Calcitonin", optionB: "Parathormone (PTH)", optionC: "Insulin", optionD: "Glucagon", correctOption: "B", explanation: "Parathormone increases blood Ca²⁺ by acting on bone, kidney, and intestine.", orderIndex: 4 },
  { id: "neet-biology-chemical-coordination-hormones-q06", topicId: "neet-biology-chemical-coordination-hormones", text: "Steroid hormones act by:", optionA: "Binding intracellular receptors and altering gene expression", optionB: "Second messengers only at the membrane", optionC: "Being pumped into cells", optionD: "Blocking enzymes outside cells", correctOption: "A", explanation: "Lipid-soluble steroid hormones enter cells and bind receptors that regulate transcription.", orderIndex: 5 },
  { id: "neet-biology-chemical-coordination-hormones-q07", topicId: "neet-biology-chemical-coordination-hormones", text: "Peptide/protein hormones typically act via:", optionA: "Membrane receptors and second messengers (e.g., cAMP)", optionB: "Entering the nucleus directly", optionC: "Diffusing into DNA", optionD: "Being stored in bone", correctOption: "A", explanation: "Water-soluble hormones bind cell-surface receptors, triggering second messengers.", orderIndex: 6 },
  { id: "neet-biology-chemical-coordination-hormones-q08", topicId: "neet-biology-chemical-coordination-hormones", text: "The hypothalamus controls the pituitary by secreting:", optionA: "Digestive enzymes", optionB: "Releasing and inhibiting hormones", optionC: "Bile", optionD: "Insulin", correctOption: "B", explanation: "The hypothalamus produces releasing/inhibiting hormones that regulate the pituitary.", orderIndex: 7 },
  { id: "neet-biology-chemical-coordination-hormones-q09", topicId: "neet-biology-chemical-coordination-hormones", text: "The hormone glucagon:", optionA: "Raises blood glucose", optionB: "Lowers blood glucose", optionC: "Stores glucose as fat", optionD: "Has no effect on glucose", correctOption: "A", explanation: "Glucagon (from alpha cells) raises blood glucose by promoting glycogen breakdown.", orderIndex: 8 },
  { id: "neet-biology-chemical-coordination-hormones-q10", topicId: "neet-biology-chemical-coordination-hormones", text: "Diabetes mellitus results from deficiency or ineffectiveness of:", optionA: "Thyroxine", optionB: "Insulin", optionC: "Adrenaline", optionD: "Growth hormone", correctOption: "B", explanation: "Inadequate insulin action raises blood glucose, causing diabetes mellitus.", orderIndex: 9 },
  { id: "neet-biology-chemical-coordination-hormones-q11", topicId: "neet-biology-chemical-coordination-hormones", text: "Melatonin, which regulates the sleep–wake cycle, is secreted by the:", optionA: "Pineal gland", optionB: "Thyroid", optionC: "Pancreas", optionD: "Adrenal", correctOption: "A", explanation: "The pineal gland secretes melatonin, regulating circadian (diurnal) rhythms.", orderIndex: 10 },
  { id: "neet-biology-chemical-coordination-hormones-q12", topicId: "neet-biology-chemical-coordination-hormones", text: "Most hormone secretion is regulated by:", optionA: "Feedback mechanisms", optionB: "Random release", optionC: "Digestion", optionD: "Muscle contraction", correctOption: "A", explanation: "Negative feedback loops keep hormone levels within a regulated range.", orderIndex: 11 },

  // ── New topic: Sexual Reproduction in Flowering Plants ──
  { id: "neet-biology-sexual-reproduction-flowering-plants-q01", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "Pollen grains are produced in the:", optionA: "Ovule", optionB: "Anther (microsporangia)", optionC: "Stigma", optionD: "Ovary", correctOption: "B", explanation: "Microspores (pollen) develop in the pollen sacs (microsporangia) of the anther.", orderIndex: 0 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q02", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "Double fertilisation in angiosperms produces a zygote and a:", optionA: "Diploid endosperm", optionB: "Triploid endosperm", optionC: "Haploid embryo", optionD: "Second zygote", correctOption: "B", explanation: "One male gamete forms the zygote; the other fuses with two polar nuclei to form triploid endosperm.", orderIndex: 1 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q03", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "The transfer of pollen from anther to stigma is called:", optionA: "Fertilisation", optionB: "Pollination", optionC: "Germination", optionD: "Dispersal", correctOption: "B", explanation: "Pollination is the transfer of pollen to a receptive stigma (self- or cross-pollination).", orderIndex: 2 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q04", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "The typical mature embryo sac is:", optionA: "8-nucleate and 7-celled", optionB: "4-celled", optionC: "2-nucleate", optionD: "16-celled", correctOption: "A", explanation: "The Polygonum-type embryo sac is 7-celled and 8-nucleate.", orderIndex: 3 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q05", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "After fertilisation, the ovule develops into the:", optionA: "Fruit", optionB: "Seed", optionC: "Flower", optionD: "Endosperm", correctOption: "B", explanation: "The fertilised ovule matures into the seed; the ovary becomes the fruit.", orderIndex: 4 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q06", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "The nutritive tissue that nourishes the developing embryo is the:", optionA: "Endosperm", optionB: "Cotyledon only", optionC: "Testa", optionD: "Pericarp", correctOption: "A", explanation: "The triploid endosperm provides nutrition to the developing embryo.", orderIndex: 5 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q07", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "Formation of seeds without fertilisation is called:", optionA: "Apomixis", optionB: "Polyembryony", optionC: "Parthenocarpy", optionD: "Vivipary", correctOption: "A", explanation: "Apomixis is asexual seed formation without meiosis and fertilisation.", orderIndex: 6 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q08", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "The occurrence of more than one embryo in a seed is:", optionA: "Apomixis", optionB: "Polyembryony", optionC: "Parthenocarpy", optionD: "Pollination", correctOption: "B", explanation: "Polyembryony is the presence of multiple embryos in a single seed (e.g., in citrus).", orderIndex: 7 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q09", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "Fruit development without fertilisation, giving seedless fruit, is:", optionA: "Parthenocarpy", optionB: "Apomixis", optionC: "Polyembryony", optionD: "Double fertilisation", correctOption: "A", explanation: "Parthenocarpy produces seedless fruits without fertilisation (e.g., banana).", orderIndex: 8 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q10", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "Cross-pollination between two flowers of different plants is called:", optionA: "Autogamy", optionB: "Xenogamy", optionC: "Geitonogamy", optionD: "Cleistogamy", correctOption: "B", explanation: "Xenogamy is pollination between flowers of genetically different plants.", orderIndex: 9 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q11", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "The male gametophyte in angiosperms is the:", optionA: "Pollen grain", optionB: "Embryo sac", optionC: "Ovule", optionD: "Endosperm", correctOption: "A", explanation: "The germinated pollen grain (with the pollen tube and two male gametes) is the male gametophyte.", orderIndex: 10 },
  { id: "neet-biology-sexual-reproduction-flowering-plants-q12", topicId: "neet-biology-sexual-reproduction-flowering-plants", text: "The phenomenon of double fertilisation was discovered by:", optionA: "Nawaschin", optionB: "Mendel", optionC: "Darwin", optionD: "Strasburger", correctOption: "A", explanation: "S. Nawaschin first described double fertilisation in angiosperms.", orderIndex: 11 },

  // ── New topic: Reproductive Health ──
  { id: "neet-biology-reproductive-health-q01", topicId: "neet-biology-reproductive-health", text: "The Copper-T is an example of which contraceptive method?", optionA: "Barrier method", optionB: "Intrauterine device (IUD)", optionC: "Oral pill", optionD: "Surgical method", correctOption: "B", explanation: "Copper-T is an intrauterine device that prevents implantation/fertilisation.", orderIndex: 0 },
  { id: "neet-biology-reproductive-health-q02", topicId: "neet-biology-reproductive-health", text: "Which is a surgical method of contraception in males?", optionA: "Tubectomy", optionB: "Vasectomy", optionC: "IUD", optionD: "Oral pill", correctOption: "B", explanation: "Vasectomy cuts/ties the vas deferens in males; tubectomy is the female equivalent.", orderIndex: 1 },
  { id: "neet-biology-reproductive-health-q03", topicId: "neet-biology-reproductive-health", text: "IVF, where fertilisation occurs outside the body, produces a so-called:", optionA: "Clone", optionB: "Test-tube baby", optionC: "Transgenic baby", optionD: "Surrogate", correctOption: "B", explanation: "In-vitro fertilisation (IVF) fertilises the egg in the lab — a 'test-tube baby'.", orderIndex: 2 },
  { id: "neet-biology-reproductive-health-q04", topicId: "neet-biology-reproductive-health", text: "MTP stands for:", optionA: "Medical Termination of Pregnancy", optionB: "Male Testis Protein", optionC: "Menstrual Timing Programme", optionD: "Maternal Tissue Preservation", correctOption: "A", explanation: "MTP is the legal, medically supervised termination of pregnancy within limits.", orderIndex: 3 },
  { id: "neet-biology-reproductive-health-q05", topicId: "neet-biology-reproductive-health", text: "Which is a sexually transmitted infection (STI)?", optionA: "Malaria", optionB: "Syphilis", optionC: "Diabetes", optionD: "Tuberculosis", correctOption: "B", explanation: "Syphilis, gonorrhoea, and HIV/AIDS are sexually transmitted infections.", orderIndex: 4 },
  { id: "neet-biology-reproductive-health-q06", topicId: "neet-biology-reproductive-health", text: "Amniocentesis is a technique used to:", optionA: "Detect foetal genetic disorders", optionB: "Fertilise eggs", optionC: "Prevent pregnancy", optionD: "Deliver babies", correctOption: "A", explanation: "Amniocentesis samples amniotic fluid to detect foetal abnormalities; its misuse for sex determination is banned.", orderIndex: 5 },
  { id: "neet-biology-reproductive-health-q07", topicId: "neet-biology-reproductive-health", text: "GIFT (gamete intrafallopian transfer) involves transferring:", optionA: "An embryo to the uterus", optionB: "Gametes into the fallopian tube", optionC: "Sperm into the vagina", optionD: "An ovary", correctOption: "B", explanation: "GIFT places collected gametes into the fallopian tube for fertilisation in vivo.", orderIndex: 6 },
  { id: "neet-biology-reproductive-health-q08", topicId: "neet-biology-reproductive-health", text: "Oral contraceptive pills mainly work by:", optionA: "Preventing ovulation (hormonal)", optionB: "Physically blocking sperm", optionC: "Killing sperm", optionD: "Surgery", correctOption: "A", explanation: "Hormonal pills inhibit ovulation and alter the endometrium/cervical mucus.", orderIndex: 7 },
  { id: "neet-biology-reproductive-health-q09", topicId: "neet-biology-reproductive-health", text: "The barrier method of contraception includes:", optionA: "Condoms and diaphragms", optionB: "Copper-T", optionC: "Oral pills", optionD: "Vasectomy", correctOption: "A", explanation: "Barrier methods (condoms, diaphragms) physically prevent sperm meeting the egg.", orderIndex: 8 },
  { id: "neet-biology-reproductive-health-q10", topicId: "neet-biology-reproductive-health", text: "ICSI (intracytoplasmic sperm injection) involves:", optionA: "Injecting a single sperm directly into an egg", optionB: "Transferring an embryo", optionC: "Removing the uterus", optionD: "Freezing gametes only", correctOption: "A", explanation: "ICSI injects a sperm directly into the ovum's cytoplasm, aiding male-factor infertility.", orderIndex: 9 },
  { id: "neet-biology-reproductive-health-q11", topicId: "neet-biology-reproductive-health", text: "A natural (fertility-awareness) contraceptive method is the:", optionA: "Rhythm/periodic abstinence method", optionB: "Copper-T", optionC: "Condom", optionD: "Pill", correctOption: "A", explanation: "The rhythm method avoids intercourse during the fertile period of the cycle.", orderIndex: 10 },
  { id: "neet-biology-reproductive-health-q12", topicId: "neet-biology-reproductive-health", text: "Reproductive and Child Health (RCH) programmes primarily aim to:", optionA: "Increase population rapidly", optionB: "Create awareness and provide reproductive health facilities", optionC: "Ban all contraception", optionD: "Promote large families", correctOption: "B", explanation: "RCH programmes spread awareness and improve access to reproductive health care.", orderIndex: 11 },

  // ── New topic: Microbes in Human Welfare ──
  { id: "neet-biology-microbes-human-welfare-q01", topicId: "neet-biology-microbes-human-welfare", text: "Curd is formed from milk by the action of:", optionA: "Yeast", optionB: "Lactic acid bacteria (Lactobacillus)", optionC: "Penicillium", optionD: "Rhizobium", correctOption: "B", explanation: "Lactobacillus (LAB) curdles milk and also increases vitamin B₁₂ content.", orderIndex: 0 },
  { id: "neet-biology-microbes-human-welfare-q02", topicId: "neet-biology-microbes-human-welfare", text: "The antibiotic penicillin was obtained from:", optionA: "Penicillium notatum", optionB: "Bacillus", optionC: "Streptococcus", optionD: "Aspergillus", correctOption: "A", explanation: "Alexander Fleming discovered penicillin from the mould Penicillium notatum.", orderIndex: 1 },
  { id: "neet-biology-microbes-human-welfare-q03", topicId: "neet-biology-microbes-human-welfare", text: "The organism used to make bread and alcohol is:", optionA: "Saccharomyces cerevisiae (yeast)", optionB: "Lactobacillus", optionC: "Rhizobium", optionD: "E. coli", correctOption: "A", explanation: "Baker's/brewer's yeast ferments sugars, producing CO₂ (bread) and ethanol (alcohol).", orderIndex: 2 },
  { id: "neet-biology-microbes-human-welfare-q04", topicId: "neet-biology-microbes-human-welfare", text: "Biogas (mainly methane) is produced by:", optionA: "Methanogens", optionB: "Yeast", optionC: "Lactobacillus", optionD: "Penicillium", correctOption: "A", explanation: "Methanogenic archaea (e.g., Methanobacterium) produce methane in biogas plants.", orderIndex: 3 },
  { id: "neet-biology-microbes-human-welfare-q05", topicId: "neet-biology-microbes-human-welfare", text: "The 'holes' in Swiss cheese are produced by CO₂ from:", optionA: "Propionibacterium", optionB: "Lactobacillus", optionC: "Yeast", optionD: "Aspergillus", correctOption: "A", explanation: "Propionibacterium sharmanii releases CO₂, forming the large holes in Swiss cheese.", orderIndex: 4 },
  { id: "neet-biology-microbes-human-welfare-q06", topicId: "neet-biology-microbes-human-welfare", text: "The immunosuppressive drug cyclosporin A is obtained from:", optionA: "The fungus Trichoderma polysporum", optionB: "A bacterium", optionC: "A yeast", optionD: "A virus", correctOption: "A", explanation: "Cyclosporin A, used in organ transplants, is produced by the fungus Trichoderma.", orderIndex: 5 },
  { id: "neet-biology-microbes-human-welfare-q07", topicId: "neet-biology-microbes-human-welfare", text: "Statins, used to lower blood cholesterol, are produced by:", optionA: "Monascus purpureus (a yeast)", optionB: "Rhizobium", optionC: "E. coli", optionD: "Lactobacillus", correctOption: "A", explanation: "Statins from the yeast Monascus purpureus inhibit cholesterol synthesis.", orderIndex: 6 },
  { id: "neet-biology-microbes-human-welfare-q08", topicId: "neet-biology-microbes-human-welfare", text: "In sewage treatment, the primary role of microbes is to:", optionA: "Decompose organic matter, reducing BOD", optionB: "Add nutrients", optionC: "Increase BOD", optionD: "Produce antibiotics", correctOption: "A", explanation: "Aerobic microbes digest organic waste, lowering the biochemical oxygen demand (BOD).", orderIndex: 7 },
  { id: "neet-biology-microbes-human-welfare-q09", topicId: "neet-biology-microbes-human-welfare", text: "A biofertiliser that fixes nitrogen in rice fields is:", optionA: "Anabaena/Cyanobacteria", optionB: "Penicillium", optionC: "Yeast", optionD: "Aspergillus", correctOption: "A", explanation: "Cyanobacteria like Anabaena and Nostoc fix nitrogen, enriching paddy fields.", orderIndex: 8 },
  { id: "neet-biology-microbes-human-welfare-q10", topicId: "neet-biology-microbes-human-welfare", text: "Bacillus thuringiensis (Bt) is used as a:", optionA: "Biocontrol agent (biopesticide)", optionB: "Antibiotic", optionC: "Vaccine", optionD: "Biofertiliser", correctOption: "A", explanation: "Bt produces insecticidal crystal proteins used to control insect pests.", orderIndex: 9 },
  { id: "neet-biology-microbes-human-welfare-q11", topicId: "neet-biology-microbes-human-welfare", text: "Mycorrhiza is a symbiotic association between a fungus and:", optionA: "Plant roots", optionB: "Animal cells", optionC: "Bacteria", optionD: "Algae only", correctOption: "A", explanation: "Mycorrhizae associate fungi with plant roots, aiding phosphorus uptake.", orderIndex: 10 },
  { id: "neet-biology-microbes-human-welfare-q12", topicId: "neet-biology-microbes-human-welfare", text: "Citric acid, used in food, is produced industrially by:", optionA: "Aspergillus niger", optionB: "Lactobacillus", optionC: "Yeast", optionD: "Rhizobium", correctOption: "A", explanation: "The fungus Aspergillus niger is used for industrial citric acid production.", orderIndex: 11 },

  // ── New topic: Biotechnology & its Applications ──
  { id: "neet-biology-biotechnology-applications-q01", topicId: "neet-biology-biotechnology-applications", text: "Bt cotton is genetically engineered to be resistant to:", optionA: "Insect pests", optionB: "Drought", optionC: "Herbicides only", optionD: "Fungi", correctOption: "A", explanation: "Bt cotton carries cry genes producing insecticidal proteins against bollworms.", orderIndex: 0 },
  { id: "neet-biology-biotechnology-applications-q02", topicId: "neet-biology-biotechnology-applications", text: "The cry genes in Bt crops are derived from:", optionA: "Bacillus thuringiensis", optionB: "Agrobacterium", optionC: "E. coli", optionD: "Yeast", correctOption: "A", explanation: "cry genes from Bacillus thuringiensis encode insecticidal Cry proteins.", orderIndex: 1 },
  { id: "neet-biology-biotechnology-applications-q03", topicId: "neet-biology-biotechnology-applications", text: "Genetically engineered human insulin is marketed as:", optionA: "Humulin", optionB: "Interferon", optionC: "Cyclosporin", optionD: "Statin", correctOption: "A", explanation: "Humulin is recombinant human insulin produced in E. coli.", orderIndex: 2 },
  { id: "neet-biology-biotechnology-applications-q04", topicId: "neet-biology-biotechnology-applications", text: "Gene therapy is a technique to:", optionA: "Correct a defective gene by inserting a functional one", optionB: "Clone whole animals", optionC: "Make antibiotics", optionD: "Ferment food", correctOption: "A", explanation: "Gene therapy inserts a normal gene to compensate for a defective one (e.g., ADA deficiency).", orderIndex: 3 },
  { id: "neet-biology-biotechnology-applications-q05", topicId: "neet-biology-biotechnology-applications", text: "RNA interference (RNAi) is used in crops to:", optionA: "Silence specific genes (e.g., in pests)", optionB: "Add new proteins", optionC: "Increase mutation", optionD: "Fix nitrogen", correctOption: "A", explanation: "RNAi silences target genes; e.g., it protects tobacco against a nematode.", orderIndex: 4 },
  { id: "neet-biology-biotechnology-applications-q06", topicId: "neet-biology-biotechnology-applications", text: "The molecular diagnostic technique that detects very low amounts of a pathogen's nucleic acid is:", optionA: "PCR", optionB: "Gel electrophoresis only", optionC: "Chromatography", optionD: "Centrifugation", correctOption: "A", explanation: "PCR amplifies pathogen DNA/RNA, enabling early, sensitive diagnosis.", orderIndex: 5 },
  { id: "neet-biology-biotechnology-applications-q07", topicId: "neet-biology-biotechnology-applications", text: "ELISA is used to detect diseases by identifying:", optionA: "Antigens or antibodies", optionB: "Whole organisms only", optionC: "Bones", optionD: "Fats", correctOption: "A", explanation: "ELISA detects antigen–antibody interactions, e.g., in HIV diagnosis.", orderIndex: 6 },
  { id: "neet-biology-biotechnology-applications-q08", topicId: "neet-biology-biotechnology-applications", text: "Transgenic animals are those that have:", optionA: "A foreign gene deliberately introduced", optionB: "No genes", optionC: "Only natural mutations", optionD: "Been cloned only", correctOption: "A", explanation: "Transgenic animals carry a manipulated/foreign gene (e.g., for producing useful proteins).", orderIndex: 7 },
  { id: "neet-biology-biotechnology-applications-q09", topicId: "neet-biology-biotechnology-applications", text: "The regulatory body (in India) overseeing GM organisms is:", optionA: "GEAC", optionB: "ICMR only", optionC: "WHO", optionD: "FDA", correctOption: "A", explanation: "The Genetic Engineering Appraisal Committee (GEAC) regulates GM research and release in India.", orderIndex: 8 },
  { id: "neet-biology-biotechnology-applications-q10", topicId: "neet-biology-biotechnology-applications", text: "Biopiracy refers to:", optionA: "Unauthorised exploitation of bioresources/traditional knowledge", optionB: "Farming with GM crops", optionC: "Gene therapy", optionD: "Making insulin", correctOption: "A", explanation: "Biopiracy is the use of bio-resources or knowledge without authorisation or fair benefit-sharing.", orderIndex: 9 },
  { id: "neet-biology-biotechnology-applications-q11", topicId: "neet-biology-biotechnology-applications", text: "Human insulin (Humulin) consists of which chains joined by disulphide bonds?", optionA: "Chains A and B", optionB: "Chains X and Y", optionC: "Only one chain", optionD: "Three chains", correctOption: "A", explanation: "Mature insulin has A and B polypeptide chains linked by disulphide bridges (C-peptide removed).", orderIndex: 10 },
  { id: "neet-biology-biotechnology-applications-q12", topicId: "neet-biology-biotechnology-applications", text: "'Golden rice' was engineered to be rich in:", optionA: "Vitamin A (beta-carotene) precursor", optionB: "Vitamin C", optionC: "Iron only", optionD: "Protein", correctOption: "A", explanation: "Golden rice produces beta-carotene (provitamin A) to combat vitamin A deficiency.", orderIndex: 11 },

  // ── New topic: Organisms & Populations ──
  { id: "neet-biology-organisms-populations-q01", topicId: "neet-biology-organisms-populations", text: "The J-shaped growth curve represents:", optionA: "Logistic growth", optionB: "Exponential growth (unlimited resources)", optionC: "Zero growth", optionD: "Declining population", correctOption: "B", explanation: "Exponential (J-shaped) growth occurs when resources are unlimited: dN/dt = rN.", orderIndex: 0 },
  { id: "neet-biology-organisms-populations-q02", topicId: "neet-biology-organisms-populations", text: "The S-shaped (sigmoid) curve reflects:", optionA: "Exponential growth", optionB: "Logistic growth with a carrying capacity", optionC: "Instant extinction", optionD: "No limiting factors", correctOption: "B", explanation: "Logistic growth levels off at the carrying capacity K, forming an S-shaped curve.", orderIndex: 1 },
  { id: "neet-biology-organisms-populations-q03", topicId: "neet-biology-organisms-populations", text: "In the interaction where both species benefit, the relationship is:", optionA: "Mutualism (+/+)", optionB: "Predation (+/−)", optionC: "Competition (−/−)", optionD: "Amensalism (−/0)", correctOption: "A", explanation: "Mutualism benefits both partners (e.g., pollinators and flowering plants).", orderIndex: 2 },
  { id: "neet-biology-organisms-populations-q04", topicId: "neet-biology-organisms-populations", text: "The 'carrying capacity' (K) of an environment is the:", optionA: "Maximum population it can sustainably support", optionB: "Minimum population", optionC: "Birth rate", optionD: "Death rate", correctOption: "A", explanation: "K is the maximum population size the resources of a habitat can support long-term.", orderIndex: 3 },
  { id: "neet-biology-organisms-populations-q05", topicId: "neet-biology-organisms-populations", text: "An interaction where one benefits and the other is unaffected is:", optionA: "Commensalism (+/0)", optionB: "Mutualism", optionC: "Predation", optionD: "Competition", correctOption: "A", explanation: "Commensalism benefits one species with no effect on the other (e.g., an orchid on a tree).", orderIndex: 4 },
  { id: "neet-biology-organisms-populations-q06", topicId: "neet-biology-organisms-populations", text: "In parasitism, the relationship is:", optionA: "+/− (parasite benefits, host harmed)", optionB: "+/+", optionC: "0/0", optionD: "−/−", correctOption: "A", explanation: "A parasite benefits at the expense of its host (+/−).", orderIndex: 5 },
  { id: "neet-biology-organisms-populations-q07", topicId: "neet-biology-organisms-populations", text: "Organisms that maintain a constant internal environment despite external changes are:", optionA: "Conformers", optionB: "Regulators", optionC: "Migrators", optionD: "Dormant", correctOption: "B", explanation: "Regulators maintain homeostasis (e.g., birds and mammals thermoregulate).", orderIndex: 6 },
  { id: "neet-biology-organisms-populations-q08", topicId: "neet-biology-organisms-populations", text: "Allen's rule states that mammals in cold regions have:", optionA: "Larger ears and limbs", optionB: "Shorter ears and limbs (reduce heat loss)", optionC: "No fur", optionD: "Thin skin", correctOption: "B", explanation: "Allen's rule: colder climates favour shorter extremities to minimise heat loss.", orderIndex: 7 },
  { id: "neet-biology-organisms-populations-q09", topicId: "neet-biology-organisms-populations", text: "The number of individuals per unit area or volume is population:", optionA: "Density", optionB: "Emigration", optionC: "Natality", optionD: "Mortality", correctOption: "A", explanation: "Population density measures the number of individuals in a given area or volume.", orderIndex: 8 },
  { id: "neet-biology-organisms-populations-q10", topicId: "neet-biology-organisms-populations", text: "In the logistic equation dN/dt = rN[(K−N)/K], growth stops when:", optionA: "N = K", optionB: "N = 0", optionC: "r = 0 only", optionD: "K = 0", correctOption: "A", explanation: "When N equals K, the term (K−N)/K becomes zero and net growth stops.", orderIndex: 9 },
  { id: "neet-biology-organisms-populations-q11", topicId: "neet-biology-organisms-populations", text: "The desert kangaroo rat is adapted to survive with little water by:", optionA: "Producing concentrated urine and using metabolic water", optionB: "Drinking a lot of water", optionC: "Living underwater", optionD: "Sweating heavily", correctOption: "A", explanation: "It meets water needs internally (metabolic water) and excretes very concentrated urine.", orderIndex: 10 },
  { id: "neet-biology-organisms-populations-q12", topicId: "neet-biology-organisms-populations", text: "A population's age pyramid that is broad at the base indicates:", optionA: "A growing population", optionB: "A declining population", optionC: "A stable population", optionD: "Extinction", correctOption: "A", explanation: "A broad base (many young individuals) signals an expanding population.", orderIndex: 11 },

  // ── New topic: Environmental Issues ──
  { id: "neet-biology-environmental-issues-q01", topicId: "neet-biology-environmental-issues", text: "Eutrophication of a water body is caused by:", optionA: "Excess nutrients (nitrogen, phosphorus)", optionB: "Lack of nutrients", optionC: "High oxygen", optionD: "Low temperature", correctOption: "A", explanation: "Nutrient enrichment triggers algal blooms, later depleting oxygen and harming aquatic life.", orderIndex: 0 },
  { id: "neet-biology-environmental-issues-q02", topicId: "neet-biology-environmental-issues", text: "BOD (biochemical oxygen demand) of water indicates the amount of:", optionA: "Organic matter (pollution level)", optionB: "Dissolved salt", optionC: "Heavy metals", optionD: "Temperature", correctOption: "A", explanation: "A high BOD reflects more organic waste and greater pollution.", orderIndex: 1 },
  { id: "neet-biology-environmental-issues-q03", topicId: "neet-biology-environmental-issues", text: "The main greenhouse gas responsible for global warming is:", optionA: "Oxygen", optionB: "Carbon dioxide", optionC: "Nitrogen", optionD: "Argon", correctOption: "B", explanation: "CO₂ is the principal greenhouse gas, along with methane, N₂O, and CFCs.", orderIndex: 2 },
  { id: "neet-biology-environmental-issues-q04", topicId: "neet-biology-environmental-issues", text: "Ozone depletion in the stratosphere is mainly caused by:", optionA: "Chlorofluorocarbons (CFCs)", optionB: "Carbon dioxide", optionC: "Oxygen", optionD: "Water vapour", correctOption: "A", explanation: "CFCs release chlorine radicals that catalytically destroy ozone.", orderIndex: 3 },
  { id: "neet-biology-environmental-issues-q05", topicId: "neet-biology-environmental-issues", text: "Electrostatic precipitators are used to control:", optionA: "Air pollution (particulates)", optionB: "Water pollution", optionC: "Noise pollution", optionD: "Soil erosion", correctOption: "A", explanation: "Electrostatic precipitators remove fine particulate matter from industrial exhaust.", orderIndex: 4 },
  { id: "neet-biology-environmental-issues-q06", topicId: "neet-biology-environmental-issues", text: "The thickness of the ozone layer is measured in:", optionA: "Dobson units", optionB: "Decibels", optionC: "Pascals", optionD: "Lux", correctOption: "A", explanation: "Ozone column thickness is measured in Dobson units (DU).", orderIndex: 5 },
  { id: "neet-biology-environmental-issues-q07", topicId: "neet-biology-environmental-issues", text: "Catalytic converters in vehicles reduce emission of:", optionA: "Harmful gases like CO and NOx", optionB: "Water vapour", optionC: "Oxygen", optionD: "Nitrogen gas", correctOption: "A", explanation: "Catalytic converters convert CO, hydrocarbons, and NOx to less harmful gases.", orderIndex: 6 },
  { id: "neet-biology-environmental-issues-q08", topicId: "neet-biology-environmental-issues", text: "The international agreement to control CFCs and protect the ozone layer is the:", optionA: "Montreal Protocol", optionB: "Kyoto Protocol", optionC: "Ramsar Convention", optionD: "Rio Summit", correctOption: "A", explanation: "The Montreal Protocol (1987) phases out ozone-depleting substances like CFCs.", orderIndex: 7 },
  { id: "neet-biology-environmental-issues-q09", topicId: "neet-biology-environmental-issues", text: "Biomagnification refers to the increasing concentration of a toxicant:", optionA: "At successive trophic levels", optionB: "In water only", optionC: "In soil only", optionD: "In the atmosphere", correctOption: "A", explanation: "Non-degradable toxins (e.g., DDT) accumulate and increase up the food chain.", orderIndex: 8 },
  { id: "neet-biology-environmental-issues-q10", topicId: "neet-biology-environmental-issues", text: "The Kyoto Protocol primarily aims to reduce emissions of:", optionA: "Greenhouse gases", optionB: "CFCs only", optionC: "Particulates", optionD: "Noise", correctOption: "A", explanation: "The Kyoto Protocol targets reduction of greenhouse gas emissions to curb global warming.", orderIndex: 9 },
  { id: "neet-biology-environmental-issues-q11", topicId: "neet-biology-environmental-issues", text: "Increased UV radiation from ozone depletion can cause:", optionA: "Skin cancer and cataracts", optionB: "Improved eyesight", optionC: "Cooling of Earth", optionD: "More rainfall", correctOption: "A", explanation: "More UV-B reaching the surface increases skin cancer, cataracts, and immune suppression.", orderIndex: 10 },
  { id: "neet-biology-environmental-issues-q12", topicId: "neet-biology-environmental-issues", text: "A sustainable approach to solid waste is to:", optionA: "Reduce, reuse, and recycle", optionB: "Burn all waste openly", optionC: "Dump in rivers", optionD: "Bury without treatment", correctOption: "A", explanation: "The 3 R's — reduce, reuse, recycle — form the basis of sustainable waste management.", orderIndex: 11 }
